const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
  PageNumber, Footer, Header, HeadingLevel, PageBreak, ExternalHyperlink,
  TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

// Brand colors
const ROSE_DARK    = "6B2737";
const ROSE_MID     = "9E3F57";
const ROSE_LIGHT   = "F7EAED";
const ROSE_ACCENT  = "E8C4CE";
const GOLD         = "B8935A";
const CHARCOAL     = "2C2C2C";
const WARM_GRAY    = "F4F1F0";
const MID_GRAY     = "888888";
const LIGHT_BORDER = "DDD0D4";
const WHITE        = "FFFFFF";

// Border helpers
const thinBorder  = { style: BorderStyle.SINGLE, size: 1, color: LIGHT_BORDER };
const allBorders  = { top: thinBorder, bottom: thinBorder, left: thinBorder, right: thinBorder };
const noBorder    = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noBorders   = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };
const leftAccent  = {
  top: noBorder, bottom: noBorder, right: noBorder,
  left: { style: BorderStyle.SINGLE, size: 16, color: ROSE_MID }
};

function sp(before = 80, after = 80) {
  return new Paragraph({ spacing: { before, after }, children: [] });
}

function divider(color = ROSE_ACCENT) {
  return new Paragraph({
    spacing: { before: 200, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color, space: 1 } },
    children: []
  });
}

function coverTitle(text) {
  return new Paragraph({
    spacing: { before: 0, after: 120 },
    alignment: AlignmentType.LEFT,
    children: [new TextRun({ text, font: "Arial", size: 56, bold: true, color: WHITE })]
  });
}

function coverSub(text) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    children: [new TextRun({ text, font: "Arial", size: 22, color: ROSE_ACCENT, italics: true })]
  });
}

function coverMeta(label, value) {
  return new Paragraph({
    spacing: { before: 40, after: 40 },
    children: [
      new TextRun({ text: label + "  ", font: "Arial", size: 19, bold: true, color: ROSE_ACCENT }),
      new TextRun({ text: value, font: "Arial", size: 19, color: WHITE })
    ]
  });
}

function sectionHeader(text) {
  return new Paragraph({
    spacing: { before: 360, after: 120 },
    children: [
      new TextRun({ text: text.toUpperCase(), font: "Arial", size: 20, bold: true, color: ROSE_DARK, characterSpacing: 100 })
    ]
  });
}

function stepLabel(num, text) {
  return new Paragraph({
    spacing: { before: 280, after: 100 },
    children: [
      new TextRun({ text: `STEP ${num}   `, font: "Arial", size: 18, bold: true, color: GOLD }),
      new TextRun({ text: text.toUpperCase(), font: "Arial", size: 18, bold: true, color: ROSE_DARK, characterSpacing: 80 })
    ]
  });
}

function scriptSay(text) {
  // Main Bethany says block
  const lines = text.split('\n').filter(l => l.trim() !== '');
  const paragraphs = [];
  paragraphs.push(
    new Paragraph({
      spacing: { before: 60, after: 40 },
      children: [new TextRun({ text: "BETHANY SAYS:", font: "Arial", size: 18, bold: true, color: ROSE_MID, characterSpacing: 60 })]
    })
  );
  lines.forEach((line, i) => {
    paragraphs.push(
      new Paragraph({
        spacing: { before: i === 0 ? 60 : 40, after: 40 },
        indent: { left: 320 },
        children: [new TextRun({ text: line.trim(), font: "Arial", size: 21, color: CHARCOAL, italics: false })]
      })
    );
  });
  return paragraphs;
}

function direction(text) {
  return new Paragraph({
    spacing: { before: 100, after: 80 },
    indent: { left: 320 },
    children: [new TextRun({ text, font: "Arial", size: 18, italics: true, color: MID_GRAY })]
  });
}

function callout(label, lines, bg = ROSE_LIGHT, labelColor = ROSE_DARK) {
  const cellChildren = [
    new Paragraph({
      spacing: { before: 0, after: 100 },
      children: [new TextRun({ text: label.toUpperCase(), font: "Arial", size: 18, bold: true, color: labelColor, characterSpacing: 60 })]
    }),
    ...lines.map(line =>
      new Paragraph({
        spacing: { before: 60, after: 40 },
        children: [new TextRun({ text: line, font: "Arial", size: 19, color: CHARCOAL })]
      })
    )
  ];
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders: allBorders,
        shading: { fill: bg, type: ShadingType.CLEAR },
        margins: { top: 180, bottom: 180, left: 240, right: 240 },
        width: { size: 9360, type: WidthType.DXA },
        children: cellChildren
      })]
    })]
  });
}

function accentCallout(lines) {
  const cellChildren = lines.map((line, i) =>
    new Paragraph({
      spacing: { before: i === 0 ? 0 : 60, after: 40 },
      children: [new TextRun({ text: line, font: "Arial", size: 19, color: CHARCOAL, italics: true })]
    })
  );
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders: leftAccent,
        shading: { fill: WARM_GRAY, type: ShadingType.CLEAR },
        margins: { top: 160, bottom: 160, left: 280, right: 200 },
        width: { size: 9360, type: WidthType.DXA },
        children: cellChildren
      })]
    })]
  });
}

function probeRow(question, listen) {
  return new TableRow({
    children: [
      new TableCell({
        borders: allBorders,
        shading: { fill: ROSE_LIGHT, type: ShadingType.CLEAR },
        margins: { top: 120, bottom: 120, left: 160, right: 160 },
        width: { size: 5400, type: WidthType.DXA },
        children: [new Paragraph({ children: [new TextRun({ text: question, font: "Arial", size: 19, color: CHARCOAL })] })]
      }),
      new TableCell({
        borders: allBorders,
        shading: { fill: WARM_GRAY, type: ShadingType.CLEAR },
        margins: { top: 120, bottom: 120, left: 160, right: 160 },
        width: { size: 3960, type: WidthType.DXA },
        children: [new Paragraph({ children: [new TextRun({ text: listen, font: "Arial", size: 18, color: MID_GRAY, italics: true })] })]
      })
    ]
  });
}

function probeTable(rows) {
  const headerRow = new TableRow({
    children: [
      new TableCell({
        borders: allBorders,
        shading: { fill: ROSE_DARK, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 160, right: 160 },
        width: { size: 5400, type: WidthType.DXA },
        children: [new Paragraph({ children: [new TextRun({ text: "ASK THIS", font: "Arial", size: 18, bold: true, color: WHITE })] })]
      }),
      new TableCell({
        borders: allBorders,
        shading: { fill: ROSE_DARK, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 160, right: 160 },
        width: { size: 3960, type: WidthType.DXA },
        children: [new Paragraph({ children: [new TextRun({ text: "LISTEN FOR", font: "Arial", size: 18, bold: true, color: WHITE })] })]
      })
    ]
  });
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [5400, 3960],
    rows: [headerRow, ...rows.map(r => probeRow(r[0], r[1]))]
  });
}

function bodyText(text, bold = false) {
  return new Paragraph({
    spacing: { before: 80, after: 80 },
    children: [new TextRun({ text, font: "Arial", size: 20, color: CHARCOAL, bold })]
  });
}

function bulletItem(text) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    numbering: { reference: "bullets", level: 0 },
    children: [new TextRun({ text, font: "Arial", size: 20, color: CHARCOAL })]
  });
}

function principleItem(num, heading, body) {
  return [
    new Paragraph({
      spacing: { before: 160, after: 60 },
      children: [
        new TextRun({ text: `${num}.  `, font: "Arial", size: 20, bold: true, color: GOLD }),
        new TextRun({ text: heading, font: "Arial", size: 20, bold: true, color: ROSE_DARK })
      ]
    }),
    new Paragraph({
      spacing: { before: 40, after: 80 },
      indent: { left: 320 },
      children: [new TextRun({ text: body, font: "Arial", size: 19, color: CHARCOAL })]
    })
  ];
}

// ---- COVER PAGE ----
const coverSection = {
  properties: {
    page: {
      size: { width: 12240, height: 15840 },
      margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 }
    }
  },
  children: [
    // Full-width dark cover table
    new Table({
      width: { size: 9360, type: WidthType.DXA },
      columnWidths: [9360],
      rows: [new TableRow({
        children: [new TableCell({
          borders: noBorders,
          shading: { fill: ROSE_DARK, type: ShadingType.CLEAR },
          margins: { top: 800, bottom: 800, left: 600, right: 600 },
          width: { size: 9360, type: WidthType.DXA },
          children: [
            new Paragraph({
              spacing: { before: 0, after: 80 },
              children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 18, color: ROSE_ACCENT, bold: true, characterSpacing: 120 })]
            }),
