            })
          ]
        })]
      })]
    }),
    sp(0, 0),
    new Paragraph({ children: [new PageBreak()] })
  ]
};

// ---- BEFORE THE CALL ----
const beforeCallSection = {
  properties: {
    page: {
      size: { width: 12240, height: 15840 },
      margin: { top: 1080, right: 1440, bottom: 1080, left: 1440 }
    }
  },
  footers: {
    default: new Footer({
      children: [new Paragraph({
        tabStops: [{ type: TabStopType.RIGHT, position: TabStopPosition.MAX }],
        children: [
          new TextRun({ text: "THE LUXORA COLLECTIVE  |  Discovery Call Script: IntegraLife Spa", font: "Arial", size: 16, color: MID_GRAY }),
          new TextRun({ text: "\tPage ", font: "Arial", size: 16, color: MID_GRAY }),
          new TextRun({ children: [PageNumber.CURRENT], font: "Arial", size: 16, color: MID_GRAY })
        ]
      })]
    })
  },
  children: [
    sectionHeader("Before the Call: What You Know About Susan"),
    sp(0, 60),
    bodyText("Susan has kept a business alive and respected for 30 years in Southwest Florida. She did not inherit this. She came in as a manager, learned everything, and eventually bought it. That is not someone who gives up. That is someone who operates on will and intuition, not systems."),
    sp(0, 60),
    bodyText("The Groupon history matters. It tells you that at some point, discounting became the way she filled chairs. That is what happens when a clinic does not have a proactive acquisition system. She solved the revenue problem the way most owners do: by lowering the price. Your job today is to show her there is a better way."),
    sp(0, 60),
    bodyText("She has something most prospects do not: a physician on staff, a proprietary skincare line, and 30 years of loyalty. The foundation is exceptional. The digital infrastructure is almost nonexistent. 314 Instagram followers. No TikTok. No paid ads. No retargeting pixel. The credibility she has built in person has never been translated online."),
    sp(0, 80),
    callout("Your angle going in", [
      "Do not lead with what is broken. Lead with what she has built.",
      "Fort Myers and Cape Coral are growing fast. Newer, well-funded spas are entering the market with polished systems.",
      "IntegraLife has the credibility, the clinical depth, and the loyalty to dominate. But only if the infrastructure catches up to the quality of the treatments.",
      "She does not have a talent problem. She has a visibility and systems problem. Both are fixable."
    ], ROSE_LIGHT, ROSE_DARK),
    sp(0, 80),
    accentCallout([
      "The goal of this call is not to tell her what is broken.",
      "It is to show her that the foundation she has built is strong enough to scale, and that we are the team to help her do it without it falling apart in the process."
    ]),
    new Paragraph({ children: [new PageBreak()] })
  ]
};

// ---- THE CALL SCRIPT ----
const callScriptSection = {
  properties: {
    page: {
      size: { width: 12240, height: 15840 },
      margin: { top: 1080, right: 1440, bottom: 1080, left: 1440 }
    }
  },
  footers: {
    default: new Footer({
      children: [new Paragraph({
        tabStops: [{ type: TabStopType.RIGHT, position: TabStopPosition.MAX }],
        children: [
          new TextRun({ text: "THE LUXORA COLLECTIVE  |  Discovery Call Script: IntegraLife Spa", font: "Arial", size: 16, color: MID_GRAY }),
          new TextRun({ text: "\tPage ", font: "Arial", size: 16, color: MID_GRAY }),
          new TextRun({ children: [PageNumber.CURRENT], font: "Arial", size: 16, color: MID_GRAY })
        ]
      })]
    })
  },
  children: [

    sectionHeader("The Call Script"),
    sp(0, 40),
    bodyText("This call is not a sales call. It is a trust call that happens to end with an enrollment. When Susan feels fully understood before you ever describe the program, the close is not a moment. It is a natural next step.", false),
    sp(0, 120),

    // STEP 1
    stepLabel(1, "Open: Set the tone in the first 60 seconds"),
    divider(),
    ...[
      direction("[Join the call on time. Let her settle for 5 seconds before you speak. Calm, warm, unhurried.]"),
      ...scriptSay(
        '"Hey Susan, really glad we got to connect today.\n\nBefore we dive in, I just want you to know, this is not a sales call for me.\n\nMy goal today is to genuinely understand what is going on in your business, where you feel like things are working, and where you feel stuck.\n\nIf there is a real opportunity for us to help, I will walk you through exactly what that looks like. If not, I will point you in the right direction either way.\n\nSound fair?"'
      ),
      direction("[Wait for yes. Let the silence land. She already feels different than she did on any other call she has taken.]"),
    ],
    sp(0, 100),

    // STEP 2
    stepLabel(2, "Context: Surface-level first"),
    divider(),
    bodyText("Let her talk. Do not interrupt. Take notes using her exact words. You will mirror them back."),
    sp(0, 80),
    ...scriptSay(
      '"Walk me through the business right now. What does a typical week look like for you?"'
    ),
    direction("[Let her answer fully. Then:]"),
    ...scriptSay(
      '"How long has the spa been at its current revenue level, roughly?"\n\n"What have you tried over the last year or two to try to grow it or fix what is not working?"'
    ),
    sp(0, 100),

    callout("Susan-specific context to hold in your mind", [
      "She has been in business 30 years. She will likely lead with that pride. Honor it.",
      "She personally purchased the business after running it as a manager. She is the operator and the visionary.",
      "She has a physician on staff (Dr. Nassif) and a proprietary skincare line. These are assets she may not be monetizing fully.",
      "If she mentions Groupon or discounting, that is your signal. She has been solving an acquisition problem with price drops instead of systems."
    ], WARM_GRAY, ROSE_DARK),
    sp(0, 100),

    // STEP 3
    stepLabel(3, "Emotional Deep Dive: This is the unlock"),
    divider(),
    bodyText("This is the most important moment in the call. Do not rush. Do not move on until she has said everything she needs to say."),
    sp(0, 80),
    ...scriptSay(
      '"Let me ask you something a little different.\n\nWhat has been weighing on you the most in the business lately?"'
    ),
    direction("[Pause. Let her answer fully. Write down her exact words. You are going to use them.]"),
    ...scriptSay(
      '"Where do you feel the most stuck right now?"\n\n"What is frustrating you that you feel like you should have figured out by now?"\n\n"What is not working, even though on the outside it might look like it is?"'
    ),
    sp(0, 100),

    callout("What you are listening for with Susan specifically", [
      "Revenue inconsistency: Is next month ever uncertain even after 30 years?",
      "New client anxiety: With such a loyal base, is she dependent on repeat clients? What happens if that loyalty ages out?",
      "Digital overwhelm: She has likely been told she needs to be on TikTok or running ads. Has she tried it? Did it feel like someone else's world?",
      "Carrying it alone: Does she have staff she trusts, or is she still the center of everything?",
      "Discounting fatigue: Did she mention Groupon herself, or does she hedge around it?"
    ], ROSE_LIGHT, ROSE_DARK),
    sp(0, 100),

    // STEP 4
    stepLabel(4, "Mirror and Validate: Build trust fast"),
    divider(),
    bodyText("Use her exact words. Mirror back what she said. She needs to feel heard before she will hear you."),
    sp(0, 80),
    ...scriptSay(
      '"So what I am hearing is...\n\nYou have put in the work. You have been doing this for a long time. You have clients who love you and keep coming back.\n\nBut there is still a part of this that feels heavier than it should. Maybe inconsistent in ways you cannot fully predict. And you are carrying more of it personally than you want to be.\n\nIs that close?"'
    ),
    direction("[Let her confirm. She will often say 'yes, exactly' with real emotion. That is when trust locks in.]"),
    ...scriptSay(
      '"That is actually really common at your stage. And it is not a reflection of you or the quality of what you have built.\n\nIt is a reflection of the fact that a real revenue system was never built underneath all of this. The business grew on your effort and your relationships. Both of which are exceptional. But effort and relationships alone have a ceiling."'
    ),
    sp(0, 100),

    accentCallout([
      "If she mentions anything about TikTok, ads, or digital marketing feeling foreign or ineffective:",
      "\"That is completely understandable. Most of what gets sold to clinics like yours is built for a 2-year-old med spa with no reputation and no existing clientele. You are in a completely different position. The strategy for you looks nothing like that.\""
    ]),
    sp(0, 100),

    // STEP 5
    stepLabel(5, "Reframe the Problem: Position your authority"),
    divider(),
    bodyText("Name the real problem. Most owners think it is leads. It almost never is just leads."),
    sp(0, 80),
    ...scriptSay(
      '"Most med spa owners at your stage think they have a lead problem.\n\nBut what we see over and over again, and what I am already noticing in your situation, is that it is actually a breakdown in how five specific things connect:\n\nHow new clients are coming in.\nHow those people are actually getting booked.\nHow many of those bookings show up.\nHow the appointment converts into a real plan.\nAnd how many of those clients come back.\n\nSo even when things are coming in, it still does not feel stable. Because until those five things are connected, adding more leads just means more chaos.\n\nAnd from everything you have described, that is exactly what is happening."'
    ),
    sp(0, 100),

    // Susan-specific revenue probe table
    sectionHeader("Revenue Leaks to Probe for IntegraLife"),
    sp(0, 60),
    probeTable([
      [
        "\"How much of your revenue right now is coming from clients who have been coming for years versus new clients?\"",
        "Heavy repeat = retention strength AND vulnerability. One bad season or key departure could tank revenue."
      ],
      [
        "\"When a client leaves after a treatment, do they leave with their next appointment booked, or does your team follow up later?\"",
        "If clients are leaving without rebooking, this is one of the most expensive revenue leaks in the building."
      ],
      [
        "\"How often are your team members recommending Integraderm or your retail lines during appointments?\"",
        "Integraderm is a proprietary product. If it is only sold passively, it is massively underperforming."
      ],
      [
        "\"Is Integraderm available anywhere online, or only through the spa?\"",
        "No e-commerce = no passive product revenue. This is a fixable problem that adds recurring income without new clients."
      ],
      [
        "\"What does your no-show and cancellation rate look like? Do you have anything automated to reduce it?\"",
        "No automated reminders = expensive empty chairs every week."
      ],
      [
        "\"Have you tried paid ads before? What happened?\"",
        "Likely tried something, did not see ROI. This confirms the system-first need. Do not pitch ads. Pitch the foundation."
      ]
    ]),
    sp(0, 100),

    // STEP 6
    stepLabel(6, "Future Identity: Paint who she becomes"),
    divider(),
    bodyText("Let this land. Pause after you deliver it. She is seeing herself in that version of the business right now."),
    sp(0, 80),
    ...scriptSay(
      '"The clinics that break through this level are not doing it with more effort. They are not grinding harder.\n\nThey have predictable booking coming in without chasing it.\nThey have a team that actually knows how to convert.\nThey have structured offers that build lifetime value with every single visit.\nThey have a follow-up system that runs whether or not the owner is in the building.\n\nSo the business stops feeling reactive. It starts feeling controlled.\n\nAnd the owner gets to do the work she actually built this for.\n\nFor you, Susan, that looks like: Dr. Nassif\'s credentials and clinical results finally showing up in your marketing the way they deserve to. Integraderm becoming a real revenue channel, not just a retail shelf. And your 30 years of loyalty being the engine that drives new referrals on a system, not just word of mouth."'
    ),
    direction("[Let that land. Pause. Then move into the transition.]"),
    sp(0, 100),

    // STEP 7
    stepLabel(7, "Transition to Solution: Ask permission before you pitch"),
    divider(),
    ...scriptSay(
      '"Based on everything you have shared with me, I do see some real opportunity here. The foundation you have is genuinely strong. What is missing is the infrastructure to match it.\n\nWould you be open to me walking you through what I am seeing and what I would recommend for your specific situation?"'
    ),
    direction("[Wait for yes. Never pitch without this. The yes matters.]"),
    sp(0, 100),

    // STEP 8
    stepLabel(8, "Your Offer: Calm, clear, confident"),
    divider(),
    bodyText("Do not list every feature. State it clearly and move on. Confidence in delivery matters as much as content."),
    sp(0, 80),
    ...scriptSay(
      '"What we do is build out a full revenue system around your specific clinic.\n\nWe start by mapping your entire market and identifying exactly where your biggest opportunities are. For you, that is going to include your local competitive landscape in Fort Myers and Cape Coral, because newer well-funded spas are entering that market right now.\n\nThen we fix the backend first:\n\nThe booking process.\nThe show rate.\nThe consultation experience.\nHow your offers are structured to build lifetime value.\nYour follow-up system.\n\nOnce that foundation is solid, we build your digital presence around it and layer in paid acquisition.\n\nThe whole program runs 90 days. It is Bethany-led and built entirely around your specific numbers and your specific market."'
    ),
    sp(0, 100),

    // STEP 9
    stepLabel(9, "Risk Removal: Take away the fear of being wrong again"),
    divider(),
    ...scriptSay(
      '"We do not jump into ads or growth blindly. If we do not see a real path to ROI for your specific clinic, we will tell you that upfront before you make any decision.\n\nThat is why we always start with the Market Blueprint. So you know what is possible and what is in the way before you commit to anything bigger.\n\nYou have been building this for 30 years. The last thing you need is someone telling you to run ads without understanding what you have built."'
    ),
    direction("[She has been burned before, or watched other owners get burned. This removes the fear directly.]"),
    sp(0, 100),

    // STEP 10
    stepLabel(10, "The Close: Soft, powerful, no pressure"),
    divider(),
    ...scriptSay(
      '"Based on everything we have talked through, I do think we can help you fix what is going on here.\n\nThe next step would be getting you into the Growth Engine so we can actually build this out with you.\n\nMy question for you is:\n\nDo you feel like this is something you are ready to actually fix right now, or are you still more in the figuring-it-out phase?"'
    ),
    direction("[Two honest options. No pressure. No fake urgency. This framing disarms resistance because it gives her full permission to say she is not ready.]"),
    sp(0, 100),

    // Objection handling
    sectionHeader("Objection Handling"),
    sp(0, 60),
    callout("IF SHE SAYS SHE IS READY:", [
      "\"Perfect. Let me walk you through the next steps and what the investment looks like.\""
    ], ROSE_LIGHT, ROSE_DARK),
    sp(0, 80),
    callout("IF SHE HESITATES:", [
      "\"That is completely okay. Can I ask what is making you feel like you are still in figuring-it-out mode?\"",
      "",
      "[Let her tell you the real objection. Mirror it back. Reframe it. Then close again.]"
    ], WARM_GRAY, ROSE_DARK),
    sp(0, 80),
    callout("IF SHE SAYS 'I NEED TO THINK ABOUT IT':", [
      "\"Of course. What would make this a clear yes for you?\"",
      "",
      "Then let her answer. She will tell you exactly what the real hesitation is.",
      "",
      "Common for Susan: budget concern, timing (new spas entering market may actually speed her up), or wanting to talk to someone she trusts first (Dr. Nassif, a spouse). Address it directly."
    ], WARM_GRAY, ROSE_DARK),
    sp(0, 80),
    callout("IF SHE BRINGS UP 'WE ALREADY TRIED ADS':", [
      "\"That is actually exactly why we start with the system before we ever touch ads.",
      "Running ads to a clinic that has not fixed its booking process, show rate, and consultation conversion does not grow the business.",
      "It just scales the chaos.",
      "What we do is fix the backend first. Then, and only then, do we add fuel.",
      "The difference is everything.\""
    ], ROSE_LIGHT, ROSE_DARK),
    sp(0, 100),

    new Paragraph({ children: [new PageBreak()] }),

    // PRINCIPLES
    sectionHeader("Call Principles to Internalize"),
    sp(0, 80),
    ...principleItem(1, "The goal of the first half is to make her feel more understood than she has ever felt on a business call.", "Do not rush to the solution. The understanding IS the value."),
    ...principleItem(2, "The goal of the second half is to make the solution feel inevitable, not persuasive.", "If you have done the first half right, she is already halfway sold before you ever describe the program."),
    ...principleItem(3, "If you rush to pitch, you lose her.", "Med spa owners have been pitched constantly. They have finely tuned skepticism detectors. Earn the pitch by earning the trust."),
    ...principleItem(4, "If you make her feel seen first, she closes herself.", "This is the entire framework. Mirror, validate, reframe, paint the future, ask for permission. In that order."),
    ...principleItem(5, "Susan is proud of what she has built. Respect that and build on it.", "Never position her current business as broken. Position it as a foundation that has not had the right system built on top of it yet."),
    sp(0, 100),

    // CLOSING REFRAME CALLOUT
    callout("The Most Important Thing to Remember on This Call", [
      "Susan Bell has kept a business alive for 30 years through sheer will, expertise, and relationship.",
      "She does not need to be convinced she is capable. She already knows that.",
      "She needs to believe there is a better way forward than what she has been doing alone.",
      "Your job is not to be impressive. Your job is to be the first person who made her feel like someone actually gets what she has built, and has the system to take it further."
    ], ROSE_LIGHT, ROSE_DARK),
    sp(0, 100),

    divider(GOLD),
    new Paragraph({
      spacing: { before: 120, after: 60 },
      alignment: AlignmentType.CENTER,
      children: [new TextRun({ text: "THE LUXORA COLLECTIVE", font: "Arial", size: 18, bold: true, color: ROSE_DARK, characterSpacing: 80 })]
    }),
    new Paragraph({
      spacing: { before: 0, after: 0 },
      alignment: AlignmentType.CENTER,
      children: [new TextRun({ text: "theluxoracollective.co  |  Bethany Anne, Co-Founder & CEO", font: "Arial", size: 17, color: MID_GRAY })]
    })
  ]
};

const doc = new Document({
  numbering: {
    config: [
      {
        reference: "bullets",
        levels: [{
          level: 0,
          format: LevelFormat.BULLET,
          text: "\u2022",
          alignment: AlignmentType.LEFT,
          style: { paragraph: { indent: { left: 560, hanging: 280 } } }
        }]
      }
    ]
  },
  sections: [coverSection, beforeCallSection, callScriptSection]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync('/home/claude/IntegraLife_Discovery_Call_Script.docx', buffer);
  console.log('Done.');
});

display_content.json_block:
{"language": "javascript", "code": "const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
  PageNumber, Footer, Header, HeadingLevel, PageBreak, ExternalHyperlink,
  TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

// Brand colors
const ROSE_DARK    = "6B2737";
const ROSE_MID     = "9E3F57";
const ROSE_LIGHT   = "F7EAED";
const ROSE_ACCENT  = "E8C4CE";
const GOLD         = "B8935A";
const CHARCOAL     = "2C2C2C";
const WARM_GRAY    = "F4F1F0";
const MID_GRAY     = "888888";
const LIGHT_BORDER = "DDD0D4";
const WHITE        = "FFFFFF";

// Border helpers
const thinBorder  = { style: BorderStyle.SINGLE, size: 1, color: LIGHT_BORDER };
const allBorders  = { top: thinBorder, bottom: thinBorder, left: thinBorder, right: thinBorder };
const noBorder    = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noBorders   = { top: noBorder, bottom: noBorder, left: noBorder, right: noBorder };
const leftAccent  = {
  top: noBorder, bottom: noBorder, right: noBorder,
  left: { style: BorderStyle.SINGLE, size: 16, color: ROSE_MID }
};

function sp(before = 80, after = 80) {
  return new Paragraph({ spacing: { before, after }, children: [] });
}

function divider(color = ROSE_ACCENT) {
  return new Paragraph({
    spacing: { before: 200, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color, space: 1 } },
    children: []
  });
}

function coverTitle(text) {
  return new Paragraph({
    spacing: { before: 0, after: 120 },
    alignment: AlignmentType.LEFT,
    children: [new TextRun({ text, font: "Arial", size: 56, bold: true, color: WHITE })]
  });
}

function coverSub(text) {
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    children: [new TextRun({ text, font: "Arial", size: 22, color: ROSE_ACCENT, italics: true })]
  });
}

function coverMeta(label, value) {
  return new Paragraph({
    spacing: { before: 40, after: 40 },
    children: [
      new TextRun({ text: label + "  ", font: "Arial", size: 19, bold: true, color: ROSE_ACCENT }),
      new TextRun({ text: value, font: "Arial", size: 19, color: WHITE })
    ]
  });
}

function sectionHeader(text) {
  return new Paragraph({
    spacing: { before: 360, after: 120 },
    children: [
      new TextRun({ text: text.toUpperCase(), font: "Arial", size: 20, bold: true, color: ROSE_DARK, characterSpacing: 100 })
    ]
  });
}

function stepLabel(num, text) {
  return new Paragraph({
    spacing: { before: 280, after: 100 },
    children: [
      new TextRun({ text: `STEP ${num}   `, font: "Arial", size: 18, bold: true, color: GOLD }),
      new TextRun({ text: text.toUpperCase(), font: "Arial", size: 18, bold: true, color: ROSE_DARK, characterSpacing: 80 })
    ]
  });
}

function scriptSay(text) {
  // Main Bethany says block
  const lines = text.split('\n').filter(l => l.trim() !== '');
  const paragraphs = [];
  paragraphs.push(
    new Paragraph({
      spacing: { before: 60, after: 40 },
      children: [new TextRun({ text: "BETHANY SAYS:", font: "Arial", size: 18, bold: true, color: ROSE_MID, characterSpacing: 60 })]
    })
  );
  lines.forEach((line, i) => {
    paragraphs.push(
      new Paragraph({
        spacing: { before: i === 0 ? 60 : 40, after: 40 },
        indent: { left: 320 },
        children: [new TextRun({ text: line.trim(), font: "Arial", size: 21, color: CHARCOAL, italics: false })]
      })
    );
  });
  return paragraphs;
}

function direction(text) {
  return new Paragraph({
    spacing: { before: 100, after: 80 },
    indent: { left: 320 },
    children: [new TextRun({ text, font: "Arial", size: 18, italics: true, color: MID_GRAY })]
  });
}

function callout(label, lines, bg = ROSE_LIGHT, labelColor = ROSE_DARK) {
  const cellChildren = [
    new Paragraph({
      spacing: { before: 0, after: 100 },
      children: [new TextRun({ text: label.toUpperCase(), font: "Arial", size: 18, bold: true, color: labelColor, characterSpacing: 60 })]
    }),
    ...lines.map(line =>
      new Paragraph({
        spacing: { before: 60, after: 40 },
        children: [new TextRun({ text: line, font: "Arial", size: 19, color: CHARCOAL })]
      })
    )
  ];
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders: allBorders,
        shading: { fill: bg, type: ShadingType.CLEAR },
        margins: { top: 180, bottom: 180, left: 240, right: 240 },
        width: { size: 9360, type: WidthType.DXA },
        children: cellChildren
      })]
    })]
  });
}

function accentCallout(lines) {
  const cellChildren = lines.map((line, i) =>
    new Paragraph({
      spacing: { before: i === 0 ? 0 : 60, after: 40 },
      children: [new TextRun({ text: line, font: "Arial", size: 19, color: CHARCOAL, italics: true })]
    })
  );
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders: leftAccent,
        shading: { fill: WARM_GRAY, type: ShadingType.CLEAR },
        margins: { top: 160, bottom: 160, left: 280, right: 200 },
        width: { size: 9360, type: WidthType.DXA },
        children: cellChildren
      })]
    })]
  });
}

function probeRow(question, listen) {
  return new TableRow({
    children: [
      new TableCell({
        borders: allBorders,
        shading: { fill: ROSE_LIGHT, type: ShadingType.CLEAR },
        margins: { top: 120, bottom: 120, left: 160, right: 160 },
        width: { size: 5400, type: WidthType.DXA },
        children: [new Paragraph({ children: [new TextRun({ text: question, font: "Arial", size: 19, color: CHARCOAL })] })]
      }),
      new TableCell({
        borders: allBorders,
        shading: { fill: WARM_GRAY, type: ShadingType.CLEAR },
        margins: { top: 120, bottom: 120, left: 160, right: 160 },
        width: { size: 3960, type: WidthType.DXA },
        children: [new Paragraph({ children: [new TextRun({ text: listen, font: "Arial", size: 18, color: MID_GRAY, italics: true })] })]
      })
    ]
  });
}

function probeTable(rows) {
  const headerRow = new TableRow({
    children: [
      new TableCell({
        borders: allBorders,
        shading: { fill: ROSE_DARK, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 160, right: 160 },
        width: { size: 5400, type: WidthType.DXA },
        children: [new Paragraph({ children: [new TextRun({ text: "ASK THIS", font: "Arial", size: 18, bold: true, color: WHITE })] })]
      }),
      new TableCell({
        borders: allBorders,
        shading: { fill: ROSE_DARK, type: ShadingType.CLEAR },
