const noB    = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noAll  = { top: noB, bottom: noB, left: noB, right: noB };
const leftAcc = { top: noB, bottom: noB, right: noB, left: { style: BorderStyle.SINGLE, size: 20, color: ROSE_MID } };
const leftGold = { top: noB, bottom: noB, right: noB, left: { style: BorderStyle.SINGLE, size: 20, color: GOLD } };

// ── Helpers ──────────────────────────────────────────
function sp(b=80,a=80){ return new Paragraph({ spacing:{before:b,after:a}, children:[] }); }

function divider(color=ROSE_MID){
  return new Paragraph({
    spacing:{before:160,after:160},
    border:{ bottom:{ style:BorderStyle.SINGLE, size:6, color, space:1 } },
    children:[]
  });
}

function pageBreak(){ return new Paragraph({ children:[new PageBreak()] }); }

// Phase header — full-width dark band table
function phaseHeader(num, label, subtitle){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({
      children:[new TableCell({
        borders: noAll,
        shading:{ fill:ROSE_DARK, type:ShadingType.CLEAR },
        margins:{ top:200, bottom:200, left:320, right:320 },
        width:{ size:9360, type:WidthType.DXA },
        children:[
          new Paragraph({
            spacing:{before:0,after:60},
            children:[
              new TextRun({ text:`PHASE ${num}`, font:"Arial", size:17, bold:true, color:GOLD, characterSpacing:120 }),
              new TextRun({ text:`   ${label.toUpperCase()}`, font:"Arial", size:24, bold:true, color:WHITE, characterSpacing:80 })
            ]
          }),
          ...(subtitle ? [new Paragraph({
            spacing:{before:0,after:0},
            children:[new TextRun({ text:subtitle, font:"Arial", size:18, italics:true, color:"C8A8B0" })]
          })] : [])
        ]
      })]
    })]
  });
}

// Section label (light, between questions)
function secLabel(text){
  return new Paragraph({
    spacing:{before:280,after:80},
    children:[new TextRun({ text:text.toUpperCase(), font:"Arial", size:17, bold:true, color:ROSE_MID, characterSpacing:80 })]
  });
}

// What YOU say — the actual script line
function say(text){
  return new Paragraph({
    spacing:{before:100,after:80},
    indent:{left:0},
    children:[new TextRun({ text, font:"Arial", size:22, color:CHARCOAL })]
  });
}

// Stage direction — italic, gray
function dir(text){
  return new Paragraph({
    spacing:{before:60,after:60},
    indent:{left:320},
    children:[new TextRun({ text, font:"Arial", size:18, italics:true, color:MID_GRAY })]
  });
}

// Question bullet — the discovery Qs
function q(text){
  return new Paragraph({
    spacing:{before:80,after:60},
    numbering:{ reference:"bullets", level:0 },
    children:[new TextRun({ text, font:"Arial", size:21, color:CHARCOAL })]
  });
}

// Sub-note under a question
function note(text){
  return new Paragraph({
    spacing:{before:0,after:60},
    indent:{left:560},
    children:[new TextRun({ text, font:"Arial", size:17, italics:true, color:MID_GRAY })]
  });
}

// Callout box
function callout(label, lines, bg=ROSE_LIGHT, lc=ROSE_DARK){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({
      children:[new TableCell({
        borders: allB,
        shading:{ fill:bg, type:ShadingType.CLEAR },
        margins:{ top:160,bottom:160,left:240,right:240 },
        width:{ size:9360, type:WidthType.DXA },
        children:[
          new Paragraph({ spacing:{before:0,after:80}, children:[new TextRun({ text:label.toUpperCase(), font:"Arial", size:17, bold:true, color:lc, characterSpacing:60 })] }),
          ...lines.map(l => new Paragraph({ spacing:{before:40,after:40}, children:[new TextRun({ text:l, font:"Arial", size:19, color:CHARCOAL })] }))
        ]
      })]
    })]
  });
}

// Left-accent quote block
function accentBlock(lines, gold=false){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({
      children:[new TableCell({
        borders: gold ? leftGold : leftAcc,
        shading:{ fill:WARM_GRAY, type:ShadingType.CLEAR },
        margins:{ top:140,bottom:140,left:280,right:200 },
        width:{ size:9360, type:WidthType.DXA },
        children: lines.map((l,i) => new Paragraph({ spacing:{before:i===0?0:40,after:40}, children:[new TextRun({ text:l, font:"Arial", size:20, italics:true, color:CHARCOAL })] }))
      })]
    })]
  });
}

// Price row in pricing table
function priceRow(label, value, bg=WHITE){
  return new TableRow({
    children:[
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:100,bottom:100,left:160,right:160}, width:{size:5400,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:label, font:"Arial", size:20, color:CHARCOAL })] })] }),
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:100,bottom:100,left:160,right:160}, width:{size:3960,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:value, font:"Arial", size:20, bold:true, color:ROSE_DARK })] })] })
    ]
  });
}

function priceTable(){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[5400,3960],
    rows:[
      new TableRow({ children:[
        new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:100,bottom:100,left:160,right:160}, width:{size:5400,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:"OPTION", font:"Arial", size:18, bold:true, color:WHITE })] })] }),
        new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:100,bottom:100,left:160,right:160}, width:{size:3960,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:"INVESTMENT", font:"Arial", size:18, bold:true, color:WHITE })] })] })
      ]}),
      priceRow("Paid in Full", "$9,000", ROSE_LIGHT),
      priceRow("2-Pay", "$4,975 x 2", WHITE),
      priceRow("Financing available", "CareCredit / Cherry", WARM_GRAY),
    ]
  });
}

// ── Image ────────────────────────────────────────────
const imgData = fs.readFileSync('/home/claude/pillars.png');
// Original 1536x1024. Target width = 9360 DXA = 6.5 inches = 9360/1440*914400 = 5943600 EMU
// Maintain aspect: height = 5943600 * (1024/1536) = 3962400 EMU
const imgEMU_W = 5943600;
const imgEMU_H = 3962400;

function pillarsImage(){
  return new Paragraph({
    spacing:{before:120,after:120},
    alignment: AlignmentType.CENTER,
    children:[new ImageRun({
      type:"png",
      data: imgData,
      transformation:{ width: Math.round(imgEMU_W/914400*96), height: Math.round(imgEMU_H/914400*96) },
      // docx-js uses pixels at 96dpi; EMU = px * 914400/96 = px * 9525
      // so px = EMU / 9525
    })]
  });
}

// docx-js ImageRun transformation is in pixels (96dpi)
// 9360 DXA = 6.5 inches. At 96dpi: 6.5 * 96 = 624px wide
// Height: 624 * (1024/1536) = 416px
function pillarsImagePx(){
  return new Paragraph({
    spacing:{before:160,after:160},
    alignment: AlignmentType.CENTER,
    children:[new ImageRun({
      type:"png",
      data: imgData,
      transformation:{ width:624, height:416 },
      altText:{ title:"The Luxora Collective 3 Pillars", description:"Market Blueprint, Acquisition Engine, Revenue Multiplier", name:"pillars" }
    })]
  });
}

// ── Footer shared ────────────────────────────────────
function makeFooter(){
  return new Footer({ children:[new Paragraph({
    tabStops:[{ type:TabStopType.RIGHT, position:TabStopPosition.MAX }],
    children:[
      new TextRun({ text:"THE LUXORA COLLECTIVE  |  Discovery Call Script", font:"Arial", size:16, color:MID_GRAY }),
      new TextRun({ text:"\tPage ", font:"Arial", size:16, color:MID_GRAY }),
      new TextRun({ children:[PageNumber.CURRENT], font:"Arial", size:16, color:MID_GRAY })
    ]
  })] });
}

const pageProps = {
  page:{
    size:{ width:12240, height:15840 },
    margin:{ top:1080, right:1440, bottom:1080, left:1440 }
  }
};

// ════════════════════════════════════════════════════
// COVER
// ════════════════════════════════════════════════════
const coverChildren = [
  new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: noAll,
      shading:{ fill:ROSE_DARK, type:ShadingType.CLEAR },
      margins:{ top:1000, bottom:1000, left:720, right:720 },
      width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({ spacing:{before:0,after:80}, children:[new TextRun({ text:"THE LUXORA COLLECTIVE", font:"Arial", size:18, bold:true, color:"C8A8B0", characterSpacing:120 })] }),
        divider(GOLD),
        new Paragraph({ spacing:{before:240,after:100}, children:[new TextRun({ text:"Discovery Call Script", font:"Arial", size:56, bold:true, color:WHITE })] }),
        new Paragraph({ spacing:{before:0,after:300}, children:[new TextRun({ text:"The Luxora Limitless", font:"Arial", size:26, color:GOLD, italics:true })] }),
        new Paragraph({ spacing:{before:0,after:80}, children:[new TextRun({ text:"Read this word for word until it becomes yours.", font:"Arial", size:20, color:"C8A8B0" })] }),
        new Paragraph({ spacing:{before:40,after:40}, children:[new TextRun({ text:"Do not improvise the structure. Trust the sequence.", font:"Arial", size:20, italics:true, color:"C8A8B0" })] }),
        divider(GOLD),
        new Paragraph({ spacing:{before:200,after:0}, children:[new TextRun({ text:"Bethany Anne  |  Co-Founder & CEO", font:"Arial", size:19, color:"C8A8B0" })] }),
        new Paragraph({ spacing:{before:40,after:0}, children:[new TextRun({ text:"theluxoracollective.co", font:"Arial", size:19, color:GOLD })] }),
      ]
    })] })]
  }),
  pageBreak()
];

// ════════════════════════════════════════════════════
// PHASE 1 — OPEN
// ════════════════════════════════════════════════════
const phase1 = [
  phaseHeader(1, "Open", "Set the tone. 60 seconds. Calm and doctor-energy."),
  sp(0,100),
  say('"Hey [name], how\'s your week going so far?"'),
  dir("[They answer. Immediately continue — do not dwell.]"),
  say('"Nice. And where are you calling in from?"'),
  dir("[They answer. Immediately continue.]"),
  say('"Perfect. Alright, let\'s jump in."'),
  sp(0,80),
  divider(),
  sp(0,80),
  say('"So here\'s what I want to do. I\'ve reviewed everything you shared before the call, so I have a solid picture of where things are, but I have deeper questions.'),
  sp(0,40),
  say('My goal today is simple: I want to see if we can actually help you. If it looks like a fit, I\'ll walk you through what a partnership looks like, the numbers, and the expected ROI. If it doesn\'t make sense, I\'ll tell you directly and point you somewhere better.'),
  sp(0,40),
  say('Sound fair?"'),
  dir("[Wait for yes. Do not move on until you have it.]"),
  sp(0,100),
  divider(),
  sp(0,100),
  say('"Good. So I\'ve seen the notes, but I want to hear it directly from you.'),
  sp(0,40),
  say('What\'s going on in your business right now that made you reach out?"'),
  dir("[Let her answer fully. Write down her exact words. You will use them later.]"),
  sp(0,60),
];

// ════════════════════════════════════════════════════
// PHASE 2 — DISCOVERY
// ════════════════════════════════════════════════════
const phase2 = [
  phaseHeader(2, "Discovery", "11 areas. Go in order. Do not rush. Listen more than you talk."),
  sp(0,80),
  callout("The only rule in discovery", [
    "Write down her exact words. Not paraphrases. Her exact words.",
    "You will mirror them back in Phase 3. That is when trust locks in."
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,120),

  secLabel("1. Pain — Anchor the emotion"),
  q('"When you say you\'re stuck, what does that actually look like month to month?"'),
  q('"How long has that been going on?"'),
  q('"If this has been an issue for over a year... why now? What changed?"'),
  q('"Be honest with me — how frustrating is it knowing you\'re doing everything right clinically, but the business still isn\'t working?"'),
  q('"If nothing changes, where do you realistically see this business a year from now?"'),

  sp(0,80),
  secLabel("2. Timing — Urgency without pressure"),
  q('"If you did solve this, when would you want that to happen?"'),
  q('"Why not six months from now?"'),
  q('"Was there a moment recently where you thought: I can\'t keep doing this like this?"'),
  q('"Is today the day you finally decide to fix the foundation instead of trying another band-aid?"'),

  sp(0,80),
  secLabel("3. Finances — Reality check"),
  q('"Roughly what did the business do last month in revenue?"'),
  q('"And profit-wise, what actually made it to you?"'),
  q('"How much are you currently spending on marketing or agencies?"'),
  q('"Does that spend feel controlled and predictable, or stressful and unclear?"'),
  q('"If we could show you how to double the return on money you\'re already spending, would that be worth prioritizing?"'),

  sp(0,80),
  secLabel("4. Partner — Decision control"),
  q('"Do you make these decisions on your own, or does a partner or spouse need to be involved?"'),
  q('"If we decided this makes sense today, would anyone else need to sign off?"'),
  dir("[Find this out early. It saves you from a dead end at the close.]"),

  sp(0,80),
  secLabel("5. Current Situation — Baseline"),
  q('"How many active clients would you say you have right now?"'),
  q('"What do you think your average client spends per year?"'),
  q('"How booked are your providers or devices on an average week?"'),
  q('"How much of the business still depends on you personally?"'),
  q('"If you stepped away for two weeks, what would break?"'),

  sp(0,80),
  secLabel("6. Goals — Future pull"),
  q('"If everything worked the way it should, where do you want this business in the next 12 months?"'),
  q('"How many hours do you want to be working?"'),
  q('"What would it mean for you personally if this business finally ran without you being the bottleneck?"'),

  sp(0,80),
  secLabel("7. Past — Why others failed"),
  q('"Have you hired agencies or consultants before?"'),
  q('"What didn\'t work?"'),
  q('"What do you wish they had actually fixed but never did?"'),
  q('"Do you feel like they focused on leads... or the actual business?"'),

  sp(0,80),
  secLabel("8. Doubt — Surface objections early"),
  q('"Why do you think this hasn\'t worked yet, even though you\'ve invested so much?"'),
  q('"What do you think is actually broken underneath everything?"'),
  q('"Do you believe this is something you can realistically fix on your own?"'),

  sp(0,80),
  secLabel("9. Comparison — Eliminate alternatives"),
  q('"Are you talking to anyone else right now?"'),
  q('"If someone else promised you more leads, would that actually solve the problem?"'),
  q('"What would make you feel confident choosing one path and committing fully?"'),

  sp(0,80),
  secLabel("10. Support — Match delivery"),
  q('"In an ideal world, what kind of support do you want?"'),
  q('"Do you want strategy only, or someone actually installing this with you?"'),
  q('"How important is it that your team is trained, not just you?"'),

  sp(0,80),
  secLabel("11. Trust — Always last"),
  q('"Before we move forward, how long have you been following us?"'),
  q('"What made you trust us enough to book this call?"'),
  dir("[This tells you what is working in your marketing and gives you material to reference when you close.]"),

  sp(0,60),
  pageBreak()
];

// ════════════════════════════════════════════════════
// PHASE 3 — MIRROR + REFRAME
// ════════════════════════════════════════════════════
const phase3 = [
  phaseHeader(3, "Mirror + Reframe", "Use her exact words. She should say 'yes, exactly.'"),
  sp(0,100),

  say('"So what I\'m hearing is...'),
  sp(0,40),
  say('You\'ve been putting in the work. Things are coming in. But it still feels inconsistent and heavier than it should.'),
  sp(0,40),
  say('And it sounds like you\'re carrying most of it yourself.'),
  sp(0,40),
  say('Is that close?"'),
  dir("[Let her confirm. Do not rush past this moment.]"),
  sp(0,100),
  say('"That\'s actually really common at your stage. And honestly, it\'s not a reflection of you.'),
  sp(0,40),
  say('It\'s a reflection of the fact that no one built a real system underneath all of this."'),
  sp(0,120),
  divider(),
  sp(0,120),

  say('"Most med spa owners at your stage think they have a lead problem.'),
  sp(0,40),
  say('But what we see over and over again is that it\'s actually a breakdown across five things:'),
  sp(0,60),
  accentBlock([
    "How leads are coming in.",
    "How they\'re being booked.",
    "How many of those bookings actually show up.",
    "How the consultation converts.",
    "How many of those clients come back."
  ]),
  sp(0,80),
  say('"So even when things are coming in, it doesn\'t feel stable. Because it isn\'t.'),
  sp(0,40),
  say('And until those five things are connected, adding more leads just means more chaos."'),
  sp(0,100),
  divider(),
  sp(0,100),

  say('"The clinics that break past this level have predictable booking. A team that converts. Structured offers that build lifetime value. A follow-up system that runs whether or not you\'re in the building.'),
  sp(0,40),
  say('The owner is no longer the one holding everything together.'),
  sp(0,40),
  say('She actually gets to do the work she built this for."'),
  dir("[Pause. Let it land. She is seeing herself in that version of the business right now.]"),
  sp(0,60),
  pageBreak()
];

// ════════════════════════════════════════════════════
// PHASE 4 — THE PITCH (with infographic)
// ════════════════════════════════════════════════════
const phase4 = [
  phaseHeader(4, "The Pitch", "Ask permission first. Never pitch without it."),
  sp(0,100),

  say('"Based on everything you\'ve shared, I do see real opportunity here.'),
  sp(0,40),
  say('Would you be open to me walking you through exactly what I\'m seeing and what I\'d recommend for your specific situation?"'),
  dir("[Wait for yes. The yes matters.]"),
  sp(0,120),

  // Infographic
  new Paragraph({ spacing:{before:80,after:40}, children:[new TextRun({ text:"OUR 3 PILLARS", font:"Arial", size:20, bold:true, color:ROSE_DARK, characterSpacing:100 })] }),
  pillarsImagePx(),
  sp(0,80),

  secLabel("Pillar 1 — The Market Blueprint"),
  say('"Before we run a single ad, we map your entire market. Competitors, gaps, pricing, offers, everything. Within 72 hours you know exactly what will work before you spend."'),
  dir("Check-in: \"Does that already feel different from what you\'ve done before?\""),
  sp(0,80),

  secLabel("Pillar 2 — The Acquisition Engine"),
  say('"We don\'t hand you leads and disappear. We install the entire acquisition system, ads, AI follow-up, CRM, booking, front desk scripts, all built so your team can execute without you."'),
  dir("Check-in: \"Can you see how this solves the follow-up and team problem?\""),
  sp(0,80),

  secLabel("Pillar 3 — The Revenue Multiplier"),
  say('"This is where most agencies stop and where we start. We turn every client into $1,800 to $10,000+ in lifetime value through memberships, packages, sales training, retention systems, and referrals."'),
  dir("Check-in: \"Is this what you\'ve been missing?\""),
  sp(0,100),

  callout("Temperature check", [
    '"How are you feeling about this process overall?"',
    "",
    "If anything less than strong yes: \"What part of this are you not seeing clearly yet?\"",
    "Address it before you move to delivery."
  ], WARM_GRAY, ROSE_DARK),
  sp(0,100),

  say('"We partner for 90 days. During that time we build and install everything with you. Not theory. Not homework.'),
  sp(0,40),
  say('You get bi-weekly strategy calls, full system build-out, team training, and ongoing optimization.'),
  sp(0,40),
  say('Most clients continue after, but that\'s entirely optional."'),
  sp(0,60),
  pageBreak()
];

// ════════════════════════════════════════════════════
// PHASE 5 — PRICE + CLOSE
// ════════════════════════════════════════════════════
const phase5 = [
  phaseHeader(5, "Price + Close", "State it. Stop talking. Let the silence work."),
  sp(0,100),

  say('"To build and install The Luxora Growth Engine over 90 days, the investment is:"'),
  sp(0,80),
  priceTable(),
  sp(0,80),
  dir("[Stop talking. Silence is your close. Do not fill it. Let her sit with it.]"),
  sp(0,120),

  accentBlock([
    '"If we don\'t generate at least 2x your investment in lifetime client value within 90 days, we work for free until we do, as long as you follow the system.',
    '',
    'No agency offers that because they don\'t control the whole engine. We do."'
  ], true),
  sp(0,120),

  say('"Based on everything we\'ve discussed today, does this feel like the solution you\'ve been looking for?"'),
  dir("[Two honest options, no pressure. Let her answer.]"),
  sp(0,120),
  divider(),
  sp(0,120),

  callout("IF SHE SAYS YES", [
    '"Perfect. Let me walk you through the next steps and what getting started looks like."'
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,80),
  callout("IF SHE HESITATES", [
    '"That\'s completely okay. Can I ask what\'s making you feel like you\'re still in figuring-it-out mode?"',
    "",
    "Let her tell you the real objection. Mirror it. Reframe it. Close again."
  ], WARM_GRAY, ROSE_DARK),
  sp(0,80),
  callout("IF SHE SAYS 'I NEED TO THINK ABOUT IT'", [
    '"Of course. What would make this a clear yes for you?"',
    "",
    "Let her answer. She will tell you the real hesitation. Address it directly.",
    "Common: budget, timing, wants to talk to a partner. Get the name. Invite them to a follow-up call."
  ], WARM_GRAY, ROSE_DARK),
  sp(0,80),
  callout("IF SHE SAYS 'WE ALREADY TRIED ADS'", [
    '"That\'s exactly why we start with the system before we ever touch ads.',
    'Running ads to a clinic that hasn\'t fixed its booking, show rate, and consultation is not a growth strategy.',
    'It\'s lighting money on fire faster.',
    'We fix the backend first. Then we add the fuel. In that order."'
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,100),

  divider(GOLD),
  new Paragraph({
    spacing:{before:120,after:60},
    alignment:AlignmentType.CENTER,
    children:[new TextRun({ text:"THE LUXORA COLLECTIVE", font:"Arial", size:18, bold:true, color:ROSE_DARK, characterSpacing:80 })]
  }),
  new Paragraph({
    spacing:{before:0,after:0},
    alignment:AlignmentType.CENTER,
    children:[new TextRun({ text:"theluxoracollective.co  |  Bethany Anne, Co-Founder & CEO", font:"Arial", size:17, color:MID_GRAY })]
  })
];

// ════════════════════════════════════════════════════
// BUILD DOC
// ════════════════════════════════════════════════════
const sharedFooters = { default: makeFooter() };

const doc = new Document({
  numbering:{
    config:[{
      reference:"bullets",
      levels:[{
        level:0,
        format:LevelFormat.BULLET,
        text:"\u2022",
        alignment:AlignmentType.LEFT,
        style:{ paragraph:{ indent:{ left:560, hanging:280 } } }
      }]
    }]
  },
  sections:[
    // Cover (no footer)
    { properties:{ page:{ size:{ width:12240, height:15840 }, margin:{ top:1440, right:1440, bottom:1440, left:1440 } } }, children:coverChildren },
    // Main script (with footer)
    { properties:pageProps, footers:sharedFooters, children:[
      ...phase1,
      ...phase2,
      ...phase3,
      ...phase4,
      ...phase5
    ]}
  ]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/home/claude/Luxora_Call_Script_Limitless.docx', buf);
  console.log('Done');
});

display_content.json_block:
{"language": "javascript", "code": "const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, ImageRun,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
  PageNumber, Footer, Header, HeadingLevel, PageBreak,
  TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

// ── Colors ──────────────────────────────────────────
const ROSE_DARK   = "6B2737";
const ROSE_MID    = "9E3F57";
const ROSE_LIGHT  = "F7EAED";
const GOLD        = "B8935A";
const CHARCOAL    = "2C2C2C";
const WARM_GRAY   = "F4F1F0";
const MID_GRAY    = "888888";
const WHITE       = "FFFFFF";
const BORDER_CLR  = "DDD0D4";

// ── Border helpers ───────────────────────────────────
const thinB  = { style: BorderStyle.SINGLE, size: 1, color: BORDER_CLR };
const allB   = { top: thinB, bottom: thinB, left: thinB, right: thinB };
const noB    = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noAll  = { top: noB, bottom: noB, left: noB, right: noB };
const leftAcc = { top: noB, bottom: noB, right: noB, left: { style: BorderStyle.SINGLE, size: 20, color: ROSE_MID } };
const leftGold = { top: noB, bottom: noB, right: noB, left: { style: BorderStyle.SINGLE, size: 20, color: GOLD } };

// ── Helpers ──────────────────────────────────────────
function sp(b=80,a=80){ return new Paragraph({ spacing:{before:b,after:a}, children:[] }); }

function divider(color=ROSE_MID){
  return new Paragraph({
    spacing:{before:160,after:160},
    border:{ bottom:{ style:BorderStyle.SINGLE, size:6, color, space:1 } },
    children:[]
  });
}

function pageBreak(){ return new Paragraph({ children:[new PageBreak()] }); }

// Phase header — full-width dark band table
function phaseHeader(num, label, subtitle){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({
      children:[new TableCell({
        borders: noAll,
        shading:{ fill:ROSE_DARK, type:ShadingType.CLEAR },
        margins:{ top:200, bottom:200, left:320, right:320 },
        width:{ size:9360, type:WidthType.DXA },
        children:[
          new Paragraph({
            spacing:{before:0,after:60},
            children:[
              new TextRun({ text:`PHASE ${num}`, font:"Arial", size:17, bold:true, color:GOLD, characterSpacing:120 }),
              new TextRun({ text:`   ${label.toUpperCase()}`, font:"Arial", size:24, bold:true, color:WHITE, characterSpacing:80 })
            ]
          }),
          ...(subtitle ? [new Paragraph({
            spacing:{before:0,after:0},
            children:[new TextRun({ text:subtitle, font:"Arial", size:18, italics:true, color:"C8A8B0" })]
          })] : [])
        ]
      })]
    })]
  });
}

// Section label (light, between questions)
function secLabel(text){
  return new Paragraph({
    spacing:{before:280,after:80},
    children:[new TextRun({ text:text.toUpperCase(), font:"Arial", size:17, bold:true, color:ROSE_MID, characterSpacing:80 })]
  });
}

// What YOU say — the actual script line
function say(text){
  return new Paragraph({
    spacing:{before:100,after:80},
    indent:{left:0},
    children:[new TextRun({ text, font:"Arial", size:22, color:CHARCOAL })]
  });
}

// Stage direction — italic, gray
function dir(text){
  return new Paragraph({
    spacing:{before:60,after:60},
    indent:{left:320},
    children:[new TextRun({ text, font:"Arial", size:18, italics:true, color:MID_GRAY })]
  });
}

// Question bullet — the discovery Qs
function q(text){
  return new Paragraph({
    spacing:{before:80,after:60},
    numbering:{ reference:"bullets", level:0 },
    children:[new TextRun({ text, font:"Arial", size:21, color:CHARCOAL })]
  });
}

// Sub-note under a question
function note(text){
  return new Paragraph({
    spacing:{before:0,after:60},
    indent:{left:560},
    children:[new TextRun({ text, font:"Arial", size:17, italics:true, color:MID_GRAY })]
  });
}

// Callout box
function callout(label, lines, bg=ROSE_LIGHT, lc=ROSE_DARK){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({
      children:[new TableCell({
        borders: allB,
        shading:{ fill:bg, type:ShadingType.CLEAR },
        margins:{ top:160,bottom:160,left:240,right:240 },
        width:{ size:9360, type:WidthType.DXA },
        children:[
          new Paragraph({ spacing:{before:0,after:80}, children:[new TextRun({ text:label.toUpperCase(), font:"Arial", size:17, bold:true, color:lc, characterSpacing:60 })] }),
          ...lines.map(l => new Paragraph({ spacing:{before:40,after:40}, children:[new TextRun({ text:l, font:"Arial", size:19, color:CHARCOAL })] }))
        ]
      })]
    })]
  });
}

// Left-accent quote block
function accentBlock(lines, gold=false){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({
      children:[new TableCell({
        borders: gold ? leftGold : leftAcc,
        shading:{ fill:WARM_GRAY, type:ShadingType.CLEAR },
        margins:{ top:140,bottom:140,left:280,right:200 },
        width:{ size:9360, type:WidthType.DXA },
        children: lines.map((l,i) => new Paragraph({ spacing:{before:i===0?0:40,after:40}, children:[new TextRun({ text:l, font:"Arial", size:20, italics:true, color:CHARCOAL })] }))
      })]
    })]
  });
}

// Price row in pricing table
function priceRow(label, value, bg=WHITE){
  return new TableRow({
    children:[
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:100,bottom:100,left:160,right:160}, width:{size:5400,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:label, font:"Arial", size:20, color:CHARCOAL })] })] }),
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:100,bottom:100,left:160,right:160}, width:{size:3960,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:value, font:"Arial", size:20, bold:true, color:ROSE_DARK })] })] })
    ]
  });
}

function priceTable(){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[5400,3960],
    rows:[
      new TableRow({ children:[
        new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:100,bottom:100,left:160,right:160}, width:{size:5400,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:"OPTION", font:"Arial", size:18, bold:true, color:WHITE })] })] }),
        new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:100,bottom:100,left:160,right:160}, width:{size:3960,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:"INVESTMENT", font:"Arial", size:18, bold:true, color:WHITE })] })] })
      ]}),
      priceRow("Paid in Full", "$9,000", ROSE_LIGHT),
      priceRow("2-Pay", "$4,975 x 2", WHITE),
      priceRow("Financing available", "CareCredit / Cherry", WARM_GRAY),
    ]
  });
}

// ── Image ────────────────────────────────────────────
const imgData = fs.readFileSync('/home/claude/pillars.png');
// Original 1536x1024. Target width = 9360 DXA = 6.5 inches = 9360/1440*914400 = 5943600 EMU
// Maintain aspect: height = 5943600 * (1024/1536) = 3962400 EMU
const imgEMU_W = 5943600;
const imgEMU_H = 3962400;

function pillarsImage(){
  return new Paragraph({
    spacing:{before:120,after:120},
    alignment: AlignmentType.CENTER,
    children:[new ImageRun({
      type:"png",
      data: imgData,
      transformation:{ width: Math.round(imgEMU_W/914400*96), height: Math.round(imgEMU_H/914400*96) },
      // docx-js uses pixels at 96dpi; EMU = px * 914400/96 = px * 9525
      // so px = EMU / 9525
    })]
  });
}

// docx-js ImageRun transformation is in pixels (96dpi)
// 9360 DXA = 6.5 inches. At 96dpi: 6.5 * 96 = 624px wide
// Height: 624 * (1024/1536) = 416px
function pillarsImagePx(){
  return new Paragraph({
    spacing:{before:160,after:160},
    alignment: AlignmentType.CENTER,
    children:[new ImageRun({
      type:"png",
      data: imgData,
      transformation:{ width:624, height:416 },
      altText:{ title:"The Luxora Collective 3 Pillars", description:"Market Blueprint, Acquisition Engine, Revenue Multiplier", name:"pillars" }
    })]
  });
}

