const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, ImageRun,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
  PageNumber, Footer, HeadingLevel, PageBreak,
  TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

// ── Brand colors ─────────────────────────────────────
const ROSE_DARK   = "6B2737";
const ROSE_MID    = "9E3F57";
const ROSE_LIGHT  = "F7EAED";
const GOLD        = "B8935A";
const CHARCOAL    = "2C2C2C";
const WARM_GRAY   = "F4F1F0";
const MID_GRAY    = "888888";
const WHITE       = "FFFFFF";
const BORDER_CLR  = "DDD0D4";
const CREAM       = "FDF8F5";

// ── Borders ──────────────────────────────────────────
const thinB   = { style: BorderStyle.SINGLE, size: 1, color: BORDER_CLR };
const allB    = { top: thinB, bottom: thinB, left: thinB, right: thinB };
const noB     = { style: BorderStyle.NONE,   size: 0, color: WHITE };
const noAll   = { top: noB, bottom: noB, left: noB, right: noB };
const leftRose = { top: noB, bottom: noB, right: noB, left: { style: BorderStyle.SINGLE, size: 20, color: ROSE_MID } };
const leftGold = { top: noB, bottom: noB, right: noB, left: { style: BorderStyle.SINGLE, size: 20, color: GOLD } };

// ── Layout helpers ───────────────────────────────────
function sp(b=80, a=80){ return new Paragraph({ spacing:{before:b,after:a}, children:[] }); }

function divider(color=ROSE_LIGHT){
  return new Paragraph({
    spacing:{before:180,after:180},
    border:{ bottom:{ style:BorderStyle.SINGLE, size:6, color, space:1 } },
    children:[]
  });
}

function pageBreak(){ return new Paragraph({ children:[new PageBreak()] }); }

// ── Phase header band ────────────────────────────────
function phaseHeader(num, label, subtitle){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: noAll,
      shading:{ fill:ROSE_DARK, type:ShadingType.CLEAR },
      margins:{ top:220, bottom:220, left:360, right:360 },
      width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({
          spacing:{before:0,after:60},
          children:[
            new TextRun({ text:`PHASE ${num}  `, font:"Arial", size:17, bold:true, color:GOLD, characterSpacing:120 }),
            new TextRun({ text:label.toUpperCase(), font:"Arial", size:25, bold:true, color:WHITE, characterSpacing:80 })
          ]
        }),
        ...(subtitle ? [new Paragraph({
          spacing:{before:0,after:0},
          children:[new TextRun({ text:subtitle, font:"Arial", size:18, italics:true, color:"C8A8B0" })]
        })] : [])
      ]
    })] })]
  });
}

// ── Section label ────────────────────────────────────
function secLabel(text){
  return new Paragraph({
    spacing:{before:280,after:80},
    children:[new TextRun({ text:text.toUpperCase(), font:"Arial", size:17, bold:true, color:ROSE_MID, characterSpacing:80 })]
  });
}

// ── What you say — readable script line ─────────────
function say(text){
  return new Paragraph({
    spacing:{before:100,after:80},
    children:[new TextRun({ text, font:"Arial", size:22, color:CHARCOAL })]
  });
}

// ── Stage direction — italic gray ────────────────────
function dir(text){
  return new Paragraph({
    spacing:{before:60,after:60},
    indent:{left:360},
    children:[new TextRun({ text, font:"Arial", size:18, italics:true, color:MID_GRAY })]
  });
}

// ── Discovery question bullet ────────────────────────
function q(text){
  return new Paragraph({
    spacing:{before:80,after:60},
    numbering:{ reference:"bullets", level:0 },
    children:[new TextRun({ text, font:"Arial", size:21, color:CHARCOAL })]
  });
}

// ── Listen-for note under a question ────────────────
function listenFor(text){
  return new Paragraph({
    spacing:{before:0,after:60},
    indent:{left:560},
    children:[
      new TextRun({ text:"Listen for:  ", font:"Arial", size:17, bold:true, color:ROSE_MID }),
      new TextRun({ text, font:"Arial", size:17, italics:true, color:MID_GRAY })
    ]
  });
}

// ── Body text ────────────────────────────────────────
function body(text){
  return new Paragraph({
    spacing:{before:80,after:80},
    children:[new TextRun({ text, font:"Arial", size:20, color:CHARCOAL })]
  });
}

// ── Callout box ──────────────────────────────────────
function callout(label, lines, bg=ROSE_LIGHT, lc=ROSE_DARK){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: allB,
      shading:{ fill:bg, type:ShadingType.CLEAR },
      margins:{ top:160,bottom:160,left:240,right:240 },
      width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({ spacing:{before:0,after:80}, children:[new TextRun({ text:label.toUpperCase(), font:"Arial", size:17, bold:true, color:lc, characterSpacing:60 })] }),
        ...lines.map(l => new Paragraph({ spacing:{before:40,after:40}, children:[new TextRun({ text:l, font:"Arial", size:19, color:CHARCOAL })] }))
      ]
    })] })]
  });
}

// ── Left-accent block (key principles / reframes) ───
function accent(lines, gold=false){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: gold ? leftGold : leftRose,
      shading:{ fill:WARM_GRAY, type:ShadingType.CLEAR },
      margins:{ top:140,bottom:140,left:280,right:200 },
      width:{ size:9360, type:WidthType.DXA },
      children: lines.map((l,i) => new Paragraph({
        spacing:{before:i===0?0:40,after:40},
        children:[new TextRun({ text:l, font:"Arial", size:20, italics:true, color:CHARCOAL })]
      }))
    })] })]
  });
}

// ── Pricing table ────────────────────────────────────
function priceTable(){
  const hRow = new TableRow({ children:[
    new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:100,bottom:100,left:160,right:160}, width:{size:5400,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:"OPTION", font:"Arial", size:18, bold:true, color:WHITE })] })] }),
    new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:100,bottom:100,left:160,right:160}, width:{size:3960,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:"INVESTMENT", font:"Arial", size:18, bold:true, color:WHITE })] })] })
  ]});
  function row(a,b,bg=WHITE){
    return new TableRow({ children:[
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:100,bottom:100,left:160,right:160}, width:{size:5400,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:a, font:"Arial", size:20, color:CHARCOAL })] })] }),
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:100,bottom:100,left:160,right:160}, width:{size:3960,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:b, font:"Arial", size:20, bold:true, color:ROSE_DARK })] })] })
    ]});
  }
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[5400,3960],
    rows:[
      hRow,
      row("Paid in Full", "$9,000", ROSE_LIGHT),
      row("2-Pay", "$4,975 × 2", WHITE),
      row("Financing available", "CareCredit / Cherry", WARM_GRAY)
    ]
  });
}

// ── Infographic image ────────────────────────────────
const imgData = fs.readFileSync('/home/claude/pillars.png');
function pillarsImage(){
  return new Paragraph({
    spacing:{before:160,after:160},
    alignment:AlignmentType.CENTER,
    children:[new ImageRun({
      type:"png",
      data: imgData,
      transformation:{ width:624, height:416 },
      altText:{ title:"The Luxora 3 Pillars", description:"Market Blueprint, Acquisition Engine, Revenue Multiplier", name:"pillars" }
    })]
  });
}

// ── Shared footer ────────────────────────────────────
function makeFooter(){
  return new Footer({ children:[new Paragraph({
    tabStops:[{ type:TabStopType.RIGHT, position:TabStopPosition.MAX }],
    children:[
      new TextRun({ text:"THE LUXORA COLLECTIVE  |  Discovery Call Script", font:"Arial", size:16, color:MID_GRAY }),
      new TextRun({ text:"\tPage ", font:"Arial", size:16, color:MID_GRAY }),
      new TextRun({ children:[PageNumber.CURRENT], font:"Arial", size:16, color:MID_GRAY })
    ]
  })] });
}

const pageProps = {
  page:{
    size:{ width:12240, height:15840 },
    margin:{ top:1080, right:1440, bottom:1080, left:1440 }
  }
};

// ════════════════════════════════════════════════════════════════
// COVER
// ════════════════════════════════════════════════════════════════
const cover = [
  new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: noAll,
      shading:{ fill:ROSE_DARK, type:ShadingType.CLEAR },
      margins:{ top:1000,bottom:1000,left:720,right:720 },
      width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({ spacing:{before:0,after:60}, children:[new TextRun({ text:"THE LUXORA COLLECTIVE", font:"Arial", size:18, bold:true, color:"C8A8B0", characterSpacing:120 })] }),
        new Paragraph({ spacing:{before:0,after:160}, border:{ bottom:{ style:BorderStyle.SINGLE, size:4, color:GOLD, space:1 } }, children:[] }),
        new Paragraph({ spacing:{before:200,after:80}, children:[new TextRun({ text:"Discovery Call Script", font:"Arial", size:56, bold:true, color:WHITE })] }),
        new Paragraph({ spacing:{before:0,after:80}, children:[new TextRun({ text:"The Luxora Limitless", font:"Arial", size:26, color:GOLD, italics:true })] }),
        new Paragraph({ spacing:{before:0,after:300}, children:[new TextRun({ text:"The feminine framework. The full question set. One script.", font:"Arial", size:20, color:"C8A8B0" })] }),
        new Paragraph({ spacing:{before:0,after:60}, children:[new TextRun({ text:"This call is not a sales call.", font:"Arial", size:21, bold:true, color:WHITE })] }),
        new Paragraph({ spacing:{before:0,after:60}, children:[new TextRun({ text:"It is a trust call that happens to end with an enrollment.", font:"Arial", size:21, color:"C8A8B0" })] }),
        new Paragraph({ spacing:{before:0,after:60}, children:[new TextRun({ text:"The difference is everything.", font:"Arial", size:21, italics:true, color:GOLD })] }),
        new Paragraph({ spacing:{before:200,after:0}, border:{ bottom:{ style:BorderStyle.SINGLE, size:4, color:GOLD, space:1 } }, children:[] }),
        new Paragraph({ spacing:{before:160,after:40}, children:[new TextRun({ text:"Read through three times before your next call.", font:"Arial", size:18, color:"C8A8B0", italics:true })] }),
        new Paragraph({ spacing:{before:0,after:160}, children:[new TextRun({ text:"The language is intentional. Every question is built to deepen emotional connection before you introduce Luxora as a solution.", font:"Arial", size:18, color:"C8A8B0", italics:true })] }),
        new Paragraph({ spacing:{before:0,after:40}, children:[new TextRun({ text:"Bethany Anne  |  Co-Founder & CEO", font:"Arial", size:19, color:"C8A8B0" })] }),
        new Paragraph({ spacing:{before:0,after:0}, children:[new TextRun({ text:"theluxoracollective.co", font:"Arial", size:19, color:GOLD })] }),
      ]
    })] })]
  }),
  pageBreak()
];

// ════════════════════════════════════════════════════════════════
// PHASE 1 — OPEN (Feminine: warm, unhurried, sets safety)
// ════════════════════════════════════════════════════════════════
const p1 = [
  phaseHeader(1, "Open", "60 seconds. Warm. Unhurried. She already feels different."),
  sp(0,100),

  say('"Hey [name], how\'s your week going so far?"'),
  dir("[They answer. Move forward immediately, do not dwell.]"),
  say('"Nice. And where are you calling in from?"'),
  dir("[They answer. Move forward.]"),
  say('"Perfect. Alright, let\'s jump in."'),
  sp(0,80),
  divider(),
  sp(0,80),

  say('"So here\'s what I want to do today.'),
  sp(0,40),
  say('I\'ve reviewed everything you shared before the call, so I have a solid understanding of your business and where things are right now. But I definitely have deeper questions.'),
  sp(0,40),
  say('My goal today is simple: I want to genuinely understand what is going on, where you feel stuck, and whether there is actually an opportunity for us to help.'),
  sp(0,40),
  say('If there is, I\'ll walk you through exactly what that would look like. If not, I\'ll point you in the right direction either way.'),
  sp(0,40),
  say('Sound fair?"'),
  dir("[Wait for yes. Let the silence land. She already feels safer than she did on any other call.]"),
  sp(0,80),
  divider(),
  sp(0,80),

  say('"Good. So like I said, I\'ve seen the notes, but I want to hear it directly from you.'),
  sp(0,40),
  say('What\'s going on in your business right now that made you reach out?"'),
  dir("[Let her talk. Do not interrupt. Take notes using her exact words. You will mirror them back later.]"),
  sp(0,60),
  pageBreak()
];

// ════════════════════════════════════════════════════════════════
// PHASE 2 — DISCOVERY (All 11 areas with feminine pacing)
// ════════════════════════════════════════════════════════════════
const p2 = [
  phaseHeader(2, "Discovery", "Go slow. Listen more than you talk. Write down her exact words."),
  sp(0,80),

  accent([
    "The goal of the first half of this call is to make her feel more understood than she has ever felt on a business call.",
    "She will tell you everything you need to close right here in Phase 2.",
    "Write down her exact emotional words. You are going to mirror them back."
  ]),
  sp(0,120),

  // ── 1. PAIN ───────────────────────────────────────
  secLabel("1. Pain — Anchor the emotion first"),
  say('"Walk me through your business right now. What does a typical week look like for you?"'),
  dir("[Let her answer fully before asking more. This is her story. Let her tell it.]"),
  sp(0,60),
  say('"Let me ask you something a little different.'),
  sp(0,40),
  say('What\'s been weighing on you the most in the business lately?"'),
  dir("[Pause. Let her answer fully. Do not rush. This is the most important moment in the call.]"),
  sp(0,60),
  q('"When you say you\'re stuck, what does that actually look like month to month?"'),
  q('"How long has that been going on?"'),
  q('"If this has been an issue for over a year, why now? What changed?"'),
  q('"Be honest with me. How frustrating is it knowing you\'re doing everything right clinically, but the business still isn\'t working the way it should?"'),
  q('"Where do you feel the most stuck right now?"'),
  q('"What\'s not working, even though on the outside it might look like it is?"'),
  q('"If nothing changes, where do you realistically see this business a year from now?"'),
  listenFor("Her exact emotional words. Write them down. You will use them in Phase 3."),
  sp(0,100),

  // ── 2. TIMING ─────────────────────────────────────
  secLabel("2. Timing — Urgency without pressure"),
  q('"If you did solve this, when would you want that to happen?"'),
  q('"Why not six months from now?"'),
  q('"Was there a moment recently where you thought: I can\'t keep doing this like this?"'),
  q('"Is today the day you finally decide to fix the foundation instead of trying another band-aid?"'),
  sp(0,100),

  // ── 3. FINANCES ───────────────────────────────────
  secLabel("3. Finances — Reality check"),
  q('"Roughly what did the business do last month in revenue?"'),
  q('"And profit-wise, what actually made it to you?"'),
  q('"How much are you currently spending on marketing or agencies?"'),
  q('"Does that spend feel controlled and predictable, or stressful and unclear?"'),
  q('"If we could show you how to double the return on money you\'re already spending, would that be worth prioritizing?"'),
  sp(0,100),

  // ── 4. PARTNER ────────────────────────────────────
  secLabel("4. Partner — Find this out early"),
  q('"Do you make these decisions on your own, or does a partner or spouse need to be involved?"'),
  q('"If we decided this makes sense today, would anyone else need to sign off?"'),
  dir("[Get a name if there is someone else. Invite them to the follow-up. Do not let this be the reason the deal dies cold.]"),
  sp(0,100),

  // ── 5. CURRENT SITUATION ──────────────────────────
  secLabel("5. Current Situation — Understand the baseline"),
  q('"How many active clients would you say you have right now?"'),
  q('"What do you think your average client spends per year?"'),
  q('"How booked are your providers or devices on an average week?"'),
  q('"How much of the business still depends on you personally?"'),
  q('"If you stepped away for two weeks, what would break?"'),
  sp(0,100),

  // ── 6. GOALS ──────────────────────────────────────
  secLabel("6. Goals — Paint the future before she sees the solution"),
  q('"If everything worked the way it should, where do you want this business in the next 12 months?"'),
  q('"How many hours do you want to be working?"'),
  q('"What would it mean for you personally if this business finally ran without you being the bottleneck?"'),
  dir("[Let that land. She is now picturing the version of her business she actually wants. That image is your close.]"),
  sp(0,100),

  // ── 7. PAST ───────────────────────────────────────
  secLabel("7. Past — Why everything else failed"),
  q('"Have you hired agencies or consultants before?"'),
  q('"What didn\'t work?"'),
  q('"What do you wish they had actually fixed but never did?"'),
  q('"Do you feel like they focused on leads, or on the actual business?"'),
  sp(0,100),

  // ── 8. DOUBT ──────────────────────────────────────
  secLabel("8. Doubt — Surface objections before the pitch"),
  q('"Why do you think this hasn\'t worked yet, even though you\'ve invested so much?"'),
  q('"What do you think is actually broken underneath everything?"'),
  q('"Do you believe this is something you can realistically fix on your own?"'),
  dir("[She will tell you her real objection right here. Write it down. You will address it before you ever name a price.]"),
  sp(0,100),

  // ── 9. COMPARISON ─────────────────────────────────
  secLabel("9. Comparison — Eliminate the alternatives"),
  q('"Are you talking to anyone else right now?"'),
  q('"If someone else promised you more leads, would that actually solve the problem?"'),
  q('"What would make you feel confident choosing one path and committing fully?"'),
  sp(0,100),

  // ── 10. SUPPORT ───────────────────────────────────
  secLabel("10. Support — Match your delivery to what she actually wants"),
  q('"In an ideal world, what kind of support do you want?"'),
  q('"Do you want strategy only, or someone actually installing this with you?"'),
  q('"How important is it that your team is trained, not just you?"'),
  sp(0,100),

  // ── 11. TRUST ─────────────────────────────────────
