        new Paragraph({ spacing:{before:0,after:160}, border:{ bottom:{ style:BorderStyle.SINGLE, size:4, color:GOLD, space:1 } }, children:[] }),
        new Paragraph({ spacing:{before:200,after:80}, children:[new TextRun({ text:"Discovery Call Script", font:"Arial", size:56, bold:true, color:WHITE })] }),
        new Paragraph({ spacing:{before:0,after:80}, children:[new TextRun({ text:"The Luxora Limitless", font:"Arial", size:26, color:GOLD, italics:true })] }),
        new Paragraph({ spacing:{before:0,after:300}, children:[new TextRun({ text:"The feminine framework. The full question set. One script.", font:"Arial", size:20, color:"C8A8B0" })] }),
