  secLabel("11. Trust — Always last"),
  q('"Before we move forward, how long have you been following us?"'),
  q('"What made you trust us enough to book this call?"'),
  dir("[This tells you what is working in your marketing and gives you language to reference when you close.]"),

  sp(0,60),
  pageBreak()
];

// ════════════════════════════════════════════════════════════════
// PHASE 3 — MIRROR + REFRAME (The emotional unlock)
// ════════════════════════════════════════════════════════════════
const p3 = [
  phaseHeader(3, "Mirror + Reframe", "Use her exact words back. She should say 'yes, exactly.'"),
  sp(0,100),

  accent([
    "Do not paraphrase. Mirror her exact words.",
    "The moment she says 'yes, exactly' with real emotion, trust has locked in.",
    "That moment is when she closes herself."
  ]),
  sp(0,120),

  say('"So what I\'m hearing is...'),
  sp(0,40),
  say('You\'ve been putting in the work. You\'ve got things coming in. But it still feels inconsistent and heavier than it should.'),
  sp(0,40),
  say('And it sounds like you\'re carrying most of it yourself.'),
  sp(0,40),
  say('Is that close?"'),
  dir("[Let her confirm. Do not rush past this. Sit in the silence.]"),
  sp(0,100),

  say('"That\'s actually really common at your stage. And honestly, it\'s not a reflection of you.'),
  sp(0,40),
  say('It\'s a reflection of the fact that no one ever built a real system underneath all of this."'),
  sp(0,100),
  divider(),
  sp(0,100),

  say('"Most med spa owners at your stage think they have a lead problem.'),
  sp(0,40),
  say('But what we see over and over again is that it\'s actually a breakdown across five specific things:"'),
  sp(0,80),

  accent([
    "How leads are coming in.",
    "How they\'re being booked.",
    "How many of those bookings actually show up.",
    "How the consultation converts.",
    "And how many of those clients come back."
  ]),
  sp(0,80),

  say('"So even when things are coming in, it doesn\'t feel stable. Because it isn\'t.'),
  sp(0,40),
  say('And until those five things are actually connected, adding more leads just means more chaos."'),
  sp(0,100),
  divider(),
  sp(0,100),

  say('"The clinics that break past this level don\'t operate like that.'),
  sp(0,40),
  say('They have predictable booking systems.'),
  say('They have a team that actually knows how to convert.'),
  say('They have structured offers that build lifetime value.'),
  sp(0,40),
  say('So the business stops feeling reactive and starts feeling controlled.'),
  sp(0,40),
  say('The owner is no longer the one holding everything together.'),
  sp(0,40),
  say('She actually gets to do the work she built this for."'),
  dir("[Let that land. Pause. She is seeing herself in that version of her business right now. Do not fill the silence.]"),
  sp(0,60),
  pageBreak()
];

// ════════════════════════════════════════════════════════════════
// PHASE 4 — THE PITCH (Permission first, then the 3 pillars)
// ════════════════════════════════════════════════════════════════
const p4 = [
  phaseHeader(4, "The Pitch", "Ask permission. Never pitch without it. The yes matters."),
  sp(0,100),

  say('"Based on everything you\'ve shared with me, I do see some real opportunity here.'),
  sp(0,40),
  say('Would you be open to me walking you through what I\'m seeing and what I\'d recommend for your specific situation?"'),
  dir("[Wait for yes. Do not move until you have it.]"),
  sp(0,120),
  divider(),
  sp(0,100),

  // Infographic
  new Paragraph({ spacing:{before:0,after:60}, children:[new TextRun({ text:"OUR 3 PILLARS", font:"Arial", size:20, bold:true, color:ROSE_DARK, characterSpacing:100 })] }),
  pillarsImage(),
  sp(0,80),

  secLabel("Pillar 1 — The Market Blueprint"),
  say('"Before we run a single ad, we map your entire market. Competitors, gaps, pricing, offers, everything.'),
  sp(0,40),
  say('Within 72 hours you know exactly what will work before you spend a dollar."'),
  dir("Check-in: \"Does that already feel different from what you\'ve done before?\""),
  sp(0,100),

  secLabel("Pillar 2 — The Acquisition Engine"),
  say('"We don\'t hand you leads and disappear. We install the entire acquisition system.'),
  sp(0,40),
  say('Ads, AI follow-up, CRM, booking, front desk scripts, all of it built so your team can execute without you."'),
  dir("Check-in: \"Can you see how this solves the follow-up and team problem you described?\""),
  sp(0,100),

  secLabel("Pillar 3 — The Revenue Multiplier"),
  say('"This is where most agencies stop. And it\'s exactly where we start.'),
  sp(0,40),
  say('We turn every client into $1,800 to $10,000+ in lifetime value through memberships, packages, sales training, retention systems, and referrals.'),
  sp(0,40),
  say('Not aggressive. It\'s care. And it\'s what separates the clinics that grow from the ones that plateau."'),
  dir("Check-in: \"Is this what you\'ve been missing?\""),
  sp(0,100),

  callout("Temperature check before delivery", [
    '"How are you feeling about all of this so far?"',
    "",
    "If anything less than strong positive: \"What part of this aren\'t you seeing clearly yet?\"",
    "Address it now. Do not move to delivery until she is with you."
  ], WARM_GRAY, ROSE_DARK),
  sp(0,100),

  say('"We partner for 90 days. During that time we build and install everything with you. Not theory. Not homework.'),
  sp(0,40),
  say('Bi-weekly strategy calls, full system build-out, team training, and ongoing optimization.'),
  sp(0,40),
  say('Most clients continue after that. But that\'s entirely optional."'),
  sp(0,60),
  pageBreak()
];

// ════════════════════════════════════════════════════════════════
// PHASE 5 — PRICE + CLOSE (Soft, powerful, no pressure)
// ════════════════════════════════════════════════════════════════
const p5 = [
  phaseHeader(5, "Price + Close", "State it clearly. Stop talking. Let the silence work."),
  sp(0,100),

  say('"To build and install The Luxora Growth Engine over the next 90 days, the investment is:"'),
  sp(0,80),
  priceTable(),
  sp(0,80),
  dir("[Stop talking. Do not fill the silence. The silence is your close.]"),
  sp(0,120),

  accent([
    '"If we don\'t generate at least 2x your investment in lifetime client value within 90 days, we work for free until we do, as long as you follow the system.',
    "",
    "No agency offers that. Because they don\'t control the whole engine. We do."
  ], true),
  sp(0,120),

  say('"Based on everything we\'ve talked through today, do you feel like this is something you\'re ready to actually fix right now, or are you still more in the figuring-it-out phase?"'),
  dir("[Two honest options. No pressure. No fake urgency. This framing gives her full permission to say she is not ready, which disarms resistance entirely.]"),
  sp(0,100),
  divider(),
  sp(0,100),

  callout("If she says she is ready:", [
    '"Perfect. Let me walk you through the next steps and what getting started looks like."'
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,80),
  callout("If she hesitates:", [
    '"That\'s completely okay. Can I ask what\'s making you feel like you\'re still in figuring-it-out mode?"',
    "",
    "[Let her tell you the real objection. Mirror it back. Reframe it. Then close again.]"
  ], WARM_GRAY, ROSE_DARK),
  sp(0,80),
  callout("If she says 'I need to think about it':", [
    '"Of course. What would make this a clear yes for you?"',
    "",
    "Let her answer. She will tell you exactly what the hesitation is.",
    "Common: budget, timing, wants to talk to a partner. Get the name. Invite them to a follow-up call.",
    "Never let it go cold without a scheduled next step."
  ], WARM_GRAY, ROSE_DARK),
  sp(0,80),
  callout("If she says 'we already tried ads':", [
    '"That\'s exactly why we start with the system before we ever touch ads.',
    "Running ads to a clinic that hasn\'t fixed its booking process, show rate, and consultation conversion is not a growth strategy.",
    "It\'s lighting money on fire faster.",
    "We fix the backend first. Then we add the fuel. In that order. Every time."
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,100),
  pageBreak(),

  // ── Call Principles ──────────────────────────────
  phaseHeader(0, "Call Principles to Internalize", "Read these before every call until they are automatic."),
  sp(0,100),

  accent([
    "The goal of the first half of the call is to make her feel more understood than she has ever felt on a business call.",
    "The goal of the second half is to make the solution feel inevitable, not persuasive."
  ]),
  sp(0,80),
  accent([
    "If you rush to pitch: you lose her.",
    "If you make her feel seen first: she closes herself."
  ], true),
  sp(0,80),
  callout("The two things that separate Luxora calls from every other call she has taken:", [
    "1.  You slow down when everyone else rushes. That alone builds more trust than any feature.",
    "2.  You mirror her exact words back to her. Not summaries. Her exact language. That is when the emotional lock happens."
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,100),

  divider(GOLD),
  new Paragraph({
    spacing:{before:120,after:60},
    alignment:AlignmentType.CENTER,
    children:[new TextRun({ text:"THE LUXORA COLLECTIVE", font:"Arial", size:18, bold:true, color:ROSE_DARK, characterSpacing:80 })]
  }),
  new Paragraph({
    spacing:{before:0,after:0},
    alignment:AlignmentType.CENTER,
    children:[new TextRun({ text:"theluxoracollective.co  |  Bethany Anne, Co-Founder & CEO", font:"Arial", size:17, color:MID_GRAY })]
  })
];

// ════════════════════════════════════════════════════════════════
// ASSEMBLE
// ════════════════════════════════════════════════════════════════
const doc = new Document({
  numbering:{
    config:[{
      reference:"bullets",
      levels:[{
        level:0,
        format:LevelFormat.BULLET,
        text:"\u2022",
        alignment:AlignmentType.LEFT,
        style:{ paragraph:{ indent:{ left:560, hanging:280 } } }
      }]
    }]
  },
  sections:[
    {
      properties:{ page:{ size:{ width:12240, height:15840 }, margin:{ top:1440,right:1440,bottom:1440,left:1440 } } },
      children: cover
    },
    {
      properties: pageProps,
      footers: { default: makeFooter() },
      children: [
        ...p1, ...p2, ...p3, ...p4, ...p5
      ]
    }
  ]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/home/claude/Luxora_Discovery_Call_Final.docx', buf);
  console.log('Done');
});
