// ════════════════════════════════════════════════════════════
// PHASE 3 — MIRROR + REFRAME
// ════════════════════════════════════════════════════════════
const p3 = [
  pbBefore(),
  phaseHeader(3, "Mirror + Reframe", "Use her exact words. Make the invisible visible."),
  sp(0,20),
  accent([
    "Do not paraphrase. Mirror her exact words back.",
    "The moment she says 'yes, exactly' with real emotion, trust has locked in.",
    "She is now ready to hear the solution."
