  dir("[Pause. She is now feeling the gap. Do not fill the silence. Let her sit with it.]"),
];

// ════════════════════════════════════════════════════════════
// PHASE 4 — PRESENT THE ASSESSMENT
// ════════════════════════════════════════════════════════════
const p4 = [
  pbBefore(),
  phaseHeader(4, "Present the Assessment", "Ask permission. Then walk her through exactly what happens."),
  sp(0,20),
  say('"Based on everything you\'ve shared, I do think this is exactly the right next step for you.'),
  sp(0,20),
  say('Would you be open to me walking you through what the assessment actually looks like and what you get out of it?"'),
  dir("[Wait for yes.]"),
  sp(0,20),
  divider(),
  sp(0,20),

  secLabel("What we do"),
  say('"Here is how it works.'),
  sp(0,20),
  say('We experience your business exactly the way a new prospective client would. We call to inquire. We book an appointment. We come in. We go through the consultation. We experience the treatment. We observe how we are handled after.'),
  sp(0,20),
  say('Your team will never know we were there. That is the entire point.'),
  sp(0,20),
  say('Because what happens when the owner is watching and what happens on a random Tuesday afternoon are very different things.'),
  sp(0,20),
  say('We see the real version."'),
  sp(0,20),

  secLabel("What she receives"),
  includedTable(),
  sp(0,20),

  secLabel("What makes it different"),
  accent([
    "This is not a review. This is a forensic look at where revenue is leaking and why.",
    "The report is 15 to 25 pages of specific findings with an action plan prioritized by impact.",
    "We are not here to tell her what is broken. We are here to show her what is possible once she can see it."
  ]),
  sp(0,20),

  callout("Temperature check", [
    '"How are you feeling about all of this so far?"',
    "",
    "If anything less than engaged: \"What part of this are you not seeing clearly yet?\"",
    "Address it before you move to price."
  ], WARM_GRAY, ROSE_DARK),
];

// ════════════════════════════════════════════════════════════
// PHASE 5 — PRICE + CLOSE
// ════════════════════════════════════════════════════════════
const p5 = [
  pbBefore(),
  phaseHeader(5, "Price + Close", "State it. Stop talking. Let the silence work."),
  sp(0,20),
  say('"The investment for the Confidential Experience Assessment is:"'),
  sp(0,20),
  priceTable(),
  sp(0,20),
  dir("[Stop talking. Do not fill the silence.]"),
  sp(0,20),
  accent([
    '"For the owner who has been running her business on instinct and hoping her client experience is what she thinks it is.',
    '$2,500 is not the cost of an assessment.',
    'It is the cost of finally seeing what your clients see.',
    'And knowing exactly what to fix."'
  ], true),
  sp(0,20),
  say('"Based on everything we\'ve talked through, do you feel like this is something you\'re ready to do right now, or are you still in the figuring-it-out phase?"'),
  dir("[Two honest options. No pressure. Let her answer.]"),
  sp(0,20),
  divider(),
  sp(0,20),

  callout("If she says yes:", [
    '"Perfect. I\'ll send you the booking link right after this call. You\'ll get a confirmation email with the pre-assessment form and everything you need to know about next steps.',
    'The whole process from booking to debrief is typically three to four weeks."'
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,20),

  callout("If she hesitates:", [
    '"That\'s completely okay. Can I ask what\'s making you feel like you\'re still in figuring-it-out mode?"',
    "",
    "Let her tell you the real objection. Mirror it. Reframe it. Then close again."
  ], WARM_GRAY, ROSE_DARK),
  sp(0,20),

  callout("If she says 'I need to think about it':", [
    '"Of course. What would make this a clear yes for you?"',
    "",
    "Let her answer. Common hesitations:",
    "  Cost: \"The average no-show rate costs a med spa $2,000+ per month. One fixed leak pays for this in 30 days.\"",
    "  Timing: \"The longer you wait, the more clients you're losing in the meantime.\"",
    "  Partner: Get the name. Schedule a follow-up call with both of them.",
  ], WARM_GRAY, ROSE_DARK),
  sp(0,20),

  callout("If she says 'I don't want my team to feel like I don't trust them':", [
    '"That\'s actually the most common thing we hear, and it\'s one of the most important things to address.',
    'This is not about trust. This is about giving your team the information they need to succeed.',
    'Most staff members who are underperforming on the client experience have never been trained otherwise.',
    'This assessment gives you the specific information to coach them, not blame them."'
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,20),

  callout("If she asks what happens after:", [
    '"After the debrief call you will have a prioritized action plan.',
    'If you want support implementing it, that is what the 90-Day Growth Engine is built for.',
    'But there is no obligation. Many owners take the report and run with it on their own.",',
    "",
    "[Do not pitch the Growth Engine unless she asks. Let the assessment stand on its own.]"
  ], WARM_GRAY, ROSE_DARK),
  sp(0,20),
  divider(GOLD),
  sp(0,20),

  // ── What happens next (process recap) ────────────
  phaseHeader(0, "What Happens After She Books", "Walk her through this so she knows exactly what to expect."),
  sp(0,20),
  say('"Once you\'re booked, here is exactly what happens:"'),
  sp(0,20),
  callout("The 5-step process", [
    "Step 1:  You complete payment and receive instant confirmation.",
    "Step 2:  You\'ll get an email with a link to schedule your initial consultation call.",
    "Step 3:  We send a brief pre-assessment form to learn about your business and what to focus on.",
    "Step 4:  We conduct the mystery shop. Your team will never know.",
    "Step 5:  You receive the 15-25 page report and we schedule your 60-minute debrief call.",
    "",
    "The full process is typically three to four weeks from booking to debrief.",
    "If your location is outside Nashville, you\'ll cover roundtrip airfare and one night hotel. We coordinate all travel details after booking."
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,20),
  divider(GOLD),

  new Paragraph({
    spacing:{before:80,after:40},
    alignment:AlignmentType.CENTER,
    children:[new TextRun({ text:"THE LUXORA COLLECTIVE", font:"Arial", size:18, bold:true, color:ROSE_DARK, characterSpacing:80 })]
  }),
  new Paragraph({
    spacing:{before:0,after:0},
    alignment:AlignmentType.CENTER,
    children:[new TextRun({ text:"theluxoracollective.co  |  Bethany Anne, Co-Founder & CEO", font:"Arial", size:17, color:MID_GRAY })]
