{"language": "javascript", "code": "const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
  PageNumber, Footer, PageBreak, TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

// ── Colors ───────────────────────────────────────────
const ROSE_DARK   = "6B2737";
const ROSE_MID    = "9E3F57";
const ROSE_LIGHT  = "F7EAED";
const GOLD        = "B8935A";
const CHARCOAL    = "2C2C2C";
const WARM_GRAY   = "F4F1F0";
const MID_GRAY    = "888888";
const WHITE       = "FFFFFF";
const BORDER_CLR  = "DDD0D4";

// ── Borders ──────────────────────────────────────────
const thinB  = { style: BorderStyle.SINGLE, size: 1, color: BORDER_CLR };
const allB   = { top: thinB, bottom: thinB, left: thinB, right: thinB };
const noB    = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noAll  = { top: noB, bottom: noB, left: noB, right: noB };
const leftRose = { top: noB, bottom: noB, right: noB, left: { style: BorderStyle.SINGLE, size: 20, color: ROSE_MID } };
const leftGold = { top: noB, bottom: noB, right: noB, left: { style: BorderStyle.SINGLE, size: 20, color: GOLD } };

// ── Helpers ──────────────────────────────────────────
function sp(b=40, a=40){ return new Paragraph({ spacing:{before:b,after:a}, children:[] }); }

function divider(color=ROSE_LIGHT){
  return new Paragraph({
    spacing:{before:80,after:80},
    border:{ bottom:{ style:BorderStyle.SINGLE, size:6, color, space:1 } },
    children:[]
  });
}

function pbBefore(){
  return new Paragraph({ pageBreakBefore:true, spacing:{before:0,after:0}, children:[] });
}

// ── Phase header band ────────────────────────────────
function phaseHeader(num, label, subtitle){
  const isNumbered = num > 0;
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: noAll,
      shading:{ fill:ROSE_DARK, type:ShadingType.CLEAR },
      margins:{ top:140, bottom:140, left:360, right:360 },
      width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({
          spacing:{before:0,after:40},
          children:[
            ...(isNumbered ? [new TextRun({ text:`PHASE ${num}  `, font:"Arial", size:17, bold:true, color:GOLD, characterSpacing:120 })] : []),
            new TextRun({ text:label.toUpperCase(), font:"Arial", size:25, bold:true, color:WHITE, characterSpacing:80 })
          ]
        }),
        ...(subtitle ? [new Paragraph({
          spacing:{before:0,after:0},
          children:[new TextRun({ text:subtitle, font:"Arial", size:18, italics:true, color:"C8A8B0" })]
        })] : [])
      ]
    })] })]
  });
}

// ── Section label ────────────────────────────────────
function secLabel(text){
  return new Paragraph({
    spacing:{before:160,after:40},
    children:[new TextRun({ text:text.toUpperCase(), font:"Arial", size:17, bold:true, color:ROSE_MID, characterSpacing:80 })]
  });
}

// ── What you say ─────────────────────────────────────
function say(text){
  return new Paragraph({
    spacing:{before:60,after:40},
    children:[new TextRun({ text, font:"Arial", size:22, color:CHARCOAL })]
  });
}

// ── Stage direction ──────────────────────────────────
function dir(text){
  return new Paragraph({
    spacing:{before:40,after:40},
    indent:{left:360},
    children:[new TextRun({ text, font:"Arial", size:18, italics:true, color:MID_GRAY })]
  });
}

// ── Question bullet ──────────────────────────────────
function q(text){
  return new Paragraph({
    spacing:{before:60,after:40},
    numbering:{ reference:"bullets", level:0 },
    children:[new TextRun({ text, font:"Arial", size:21, color:CHARCOAL })]
  });
}

// ── Listen-for note ──────────────────────────────────
function listenFor(text){
  return new Paragraph({
    spacing:{before:0,after:40},
    indent:{left:560},
    children:[
      new TextRun({ text:"Listen for:  ", font:"Arial", size:17, bold:true, color:ROSE_MID }),
      new TextRun({ text, font:"Arial", size:17, italics:true, color:MID_GRAY })
    ]
  });
}

// ── Callout box ──────────────────────────────────────
function callout(label, lines, bg=ROSE_LIGHT, lc=ROSE_DARK){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: allB,
      shading:{ fill:bg, type:ShadingType.CLEAR },
      margins:{ top:100, bottom:100, left:220, right:220 },
      width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({ spacing:{before:0,after:60}, children:[new TextRun({ text:label.toUpperCase(), font:"Arial", size:17, bold:true, color:lc, characterSpacing:60 })] }),
        ...lines.map(l => new Paragraph({ spacing:{before:30,after:30}, children:[new TextRun({ text:l, font:"Arial", size:19, color:CHARCOAL })] }))
      ]
    })] })]
  });
}

// ── Left-accent block ────────────────────────────────
function accent(lines, gold=false){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: gold ? leftGold : leftRose,
      shading:{ fill:WARM_GRAY, type:ShadingType.CLEAR },
      margins:{ top:100, bottom:100, left:240, right:200 },
      width:{ size:9360, type:WidthType.DXA },
      children: lines.map((l,i) => new Paragraph({
        spacing:{before:i===0?0:30,after:30},
        children:[new TextRun({ text:l, font:"Arial", size:20, italics:true, color:CHARCOAL })]
      }))
    })] })]
  });
}

// ── Two-column what's included table ─────────────────
function includedTable(){
  function row(item, detail, bg=WHITE){
    return new TableRow({ children:[
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:160,right:160}, width:{size:3600,type:WidthType.DXA},
        children:[new Paragraph({ children:[new TextRun({ text:item, font:"Arial", size:19, bold:true, color:ROSE_DARK })] })] }),
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:160,right:160}, width:{size:5760,type:WidthType.DXA},
        children:[new Paragraph({ children:[new TextRun({ text:detail, font:"Arial", size:19, color:CHARCOAL })] })] })
    ]});
  }
  const hRow = new TableRow({ children:[
    new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:160,right:160}, width:{size:3600,type:WidthType.DXA},
      children:[new Paragraph({ children:[new TextRun({ text:"DELIVERABLE", font:"Arial", size:17, bold:true, color:WHITE })] })] }),
    new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:160,right:160}, width:{size:5760,type:WidthType.DXA},
      children:[new Paragraph({ children:[new TextRun({ text:"WHAT IT MEANS FOR HER", font:"Arial", size:17, bold:true, color:WHITE })] })] })
  ]});
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[3600, 5760],
    rows:[
      hRow,
      row("Mystery Shop", "We experience her business exactly as a new client would: phone, booking, in-person visit, follow-up.", ROSE_LIGHT),
      row("15-25 Page Report", "Comprehensive written findings with specific revenue leak identification and prioritized recommendations.", WHITE),
      row("60-Min Debrief Call", "We walk through every finding together and answer every question.", ROSE_LIGHT),
      row("Action Plan", "Quick wins and long-term strategic fixes, ranked by impact.", WHITE),
      row("30-Day Check-In", "Email follow-up one month later to track progress and answer follow-up questions.", ROSE_LIGHT),
    ]
  });
}

// ── Pricing table ────────────────────────────────────
function priceTable(){
  function row(a,b,bg=WHITE){
    return new TableRow({ children:[
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:160,right:160}, width:{size:5400,type:WidthType.DXA},
        children:[new Paragraph({ children:[new TextRun({ text:a, font:"Arial", size:20, color:CHARCOAL })] })] }),
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:160,right:160}, width:{size:3960,type:WidthType.DXA},
        children:[new Paragraph({ children:[new TextRun({ text:b, font:"Arial", size:20, bold:true, color:ROSE_DARK })] })] })
    ]});
  }
  const hRow = new TableRow({ children:[
    new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:160,right:160}, width:{size:5400,type:WidthType.DXA},
      children:[new Paragraph({ children:[new TextRun({ text:"OPTION", font:"Arial", size:17, bold:true, color:WHITE })] })] }),
    new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:160,right:160}, width:{size:3960,type:WidthType.DXA},
      children:[new Paragraph({ children:[new TextRun({ text:"INVESTMENT", font:"Arial", size:17, bold:true, color:WHITE })] })] })
  ]});
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[5400, 3960],
    rows:[
      hRow,
      row("Pay in Full", "$2,500", ROSE_LIGHT),
      row("2-Pay Plan", "$1,250 today + $1,250 before debrief", WHITE),
      row("Travel (outside Nashville)", "Roundtrip airfare + 1 night hotel", WARM_GRAY),
    ]
  });
}

function makeFooter(){
  return new Footer({ children:[new Paragraph({
    tabStops:[{ type:TabStopType.RIGHT, position:TabStopPosition.MAX }],
    children:[
      new TextRun({ text:"THE LUXORA COLLECTIVE  |  Confidential Experience Assessment", font:"Arial", size:16, color:MID_GRAY }),
      new TextRun({ text:"\tPage ", font:"Arial", size:16, color:MID_GRAY }),
      new TextRun({ children:[PageNumber.CURRENT], font:"Arial", size:16, color:MID_GRAY })
    ]
  })] });
}

const pageProps = {
  page:{ size:{ width:12240, height:15840 }, margin:{ top:1080, right:1440, bottom:1080, left:1440 } }
};

// ════════════════════════════════════════════════════════════
// COVER
// ════════════════════════════════════════════════════════════
const cover = [
  new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
