  say('"Based on everything we\'ve been through today, I do see a real path forward here. The revenue is in the business. We just need to close the leaks and build the infrastructure around it.'),
  sp(0,20),
  say('Would you be open to me walking you through exactly what that looks like?"'),
  dir("[Wait for yes.]"),
  sp(0,20),
  divider(),
  sp(0,20),
  new Paragraph({ spacing:{before:0,after:40}, children:[new TextRun({ text:"OUR 3 PILLARS", font:"Arial", size:20, bold:true, color:ROSE_DARK, characterSpacing:100 })] }),
  pillarsImage(),
  sp(0,20),

  secLabel("Pillar 1 — The Market Blueprint"),
  say('"Before we run a single ad, we map your entire market. Competitors, gaps, pricing, offers, everything.'),
  sp(0,20),
  say('This is what shows you where the opportunity actually is in your specific area, before you spend anything."'),
  dir("Check-in: \"Does that already feel different from what you\'ve done before?\""),
  sp(0,20),

  secLabel("Pillar 2 — The Acquisition Engine"),
  say('"We install the entire acquisition system. Ads, AI follow-up, CRM, booking, front desk scripts.'),
  sp(0,20),
  say('Everything your team needs to close those five leaks we just found, without you being the one who holds it together."'),
  dir("Check-in: \"Can you see how this solves what we identified in the scan?\""),
  sp(0,20),

  secLabel("Pillar 3 — The Revenue Multiplier"),
  say('"This is where we capture the money we already found in your leak scan.'),
  sp(0,20),
  say('Memberships, packages, sales training, retention sequences, referral systems. Every client becomes $1,800 to $10,000 in lifetime value instead of a one-time visit."'),
  dir("Check-in: \"Is this what you\'ve been missing?\""),
  sp(0,20),

  callout("Tie it back to her number", [
    "Before you move to delivery, reference the total from the scan:",
    "",
    '"We estimated your business is leaving around [HER TOTAL] per year on the table.',
    "The Growth Engine is built to close those specific gaps, starting in the first 30 days.",
    "By Month 3, the program has paid for itself from revenue that was already in your pipeline.",
    "We're not adding anything. We're recovering what's already yours."',
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,20),

  callout("Temperature check", [
    '"How are you feeling about all of this so far?"',
    "",
    "If anything less than a strong yes: \"What part of this are you not seeing clearly yet?\"",
    "Address it before delivery."
  ], WARM_GRAY, ROSE_DARK),
  sp(0,20),
  say('"We partner for 90 days. During that time we build and install everything with you. Not theory. Not homework.'),
  sp(0,20),
  say('Bi-weekly strategy calls, full system build-out, team training, and ongoing optimization. Most clients continue after. But that\'s entirely optional."'),
];

// ══════════════════════════════════════════════════════════
// PHASE 5 — PRICE + CLOSE
// ══════════════════════════════════════════════════════════
const p5 = [
  pbBefore(),
  phaseHeader(5, "Price + Close", "State it clearly. Stop talking. Let the silence work."),
  sp(0,20),
  say('"To build and install The Luxora Growth Engine over the next 90 days, the investment is:"'),
  sp(0,20),
  priceTable(),
  sp(0,20),
  dir("[Stop talking. Do not fill the silence.]"),
  sp(0,20),
  accent([
    '"If we don\'t generate at least 2x your investment in lifetime client value within 90 days, we work for free until we do, as long as you follow the system.',
    '',
    "No agency offers that. Because they don't control the whole engine. We do."
  ], true),
  sp(0,20),
  say('"Based on everything we\'ve talked through today, and the number we found together in the scan, do you feel like this is something you\'re ready to actually fix right now, or are you still more in the figuring-it-out phase?"'),
  dir("[Two honest options. No pressure. No fake urgency. Let her answer.]"),
  sp(0,20),
  divider(),
  sp(0,20),

  callout("If she says yes:", ['"Perfect. Let me walk you through next steps and what getting started looks like."'] , ROSE_LIGHT, ROSE_DARK),
  sp(0,20),
  callout("If she hesitates:", [
    '"That\'s completely okay. Can I ask what\'s making you feel like you\'re still in figuring-it-out mode?"',
    "", "[Let her tell you the real objection. Mirror it. Reframe it. Close again.]"
  ], WARM_GRAY, ROSE_DARK),
  sp(0,20),
  callout("If she says 'I need to think about it':", [
    '"Of course. What would make this a clear yes for you?"',
    "", "Let her answer. She will tell you the real hesitation.",
    "Common: budget, timing, needs to talk to a partner. Get the name. Schedule a follow-up with both."
  ], WARM_GRAY, ROSE_DARK),
  sp(0,20),
  callout("If she says 'we already tried ads':", [
    '"That\'s exactly why we start with the system before we ever touch ads.',
    "We just showed you the five places your business is leaking. Adding ads before closing those gaps doesn't grow the business.",
    "It just fills the leaky bucket faster.",
    "We fix the backend first. Then we add the fuel. That's the only sequence that actually works."
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,20),
  callout("If she says 'the investment is too much':", [
    "Reference the number from the scan directly:",
    "",
    '"We found [HER TOTAL] per year leaking from your business.',
    "The program is $9,000.",
    "You are not spending $9,000. You are recovering a multiple of $9,000 that is already in your pipeline.",
    "The real question is how much it costs to leave that on the table for another year."
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,20),
  divider(GOLD),
  sp(0,20),

  phaseHeader(0, "Call Principles to Internalize", "Read these before every call."),
  sp(0,20),
  accent([
    "The Revenue Leak Scan does the logic. Your job is to do the emotional work.",
    "If she can see the number and feel understood, the program is not a cost. It is the obvious next step.",
    "If you rush to pitch, you lose her. If you make her feel seen first, she closes herself."
  ]),
  sp(0,20),
  callout("The transition that wins every time", [
    "You do not say: 'So, can I tell you about our program?'",
    "You say: 'We found [HER TOTAL] leaking. Here is exactly what closes those gaps.'",
    "",
    "The scan earns the pitch. The pitch is just the answer to a question she is already asking."
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,20),
  divider(GOLD),
  new Paragraph({ spacing:{before:80,after:40}, alignment:AlignmentType.CENTER,
    children:[new TextRun({ text:"THE LUXORA COLLECTIVE", font:"Arial", size:18, bold:true, color:ROSE_DARK, characterSpacing:80 })] }),
  new Paragraph({ spacing:{before:0,after:0}, alignment:AlignmentType.CENTER,
    children:[new TextRun({ text:"theluxoracollective.co  |  Bethany Anne, Co-Founder & CEO", font:"Arial", size:17, color:MID_GRAY })] })
];

// ══════════════════════════════════════════════════════════
// BUILD
// ══════════════════════════════════════════════════════════
const doc = new Document({
  numbering:{
    config:[{
      reference:"bullets",
      levels:[{ level:0, format:LevelFormat.BULLET, text:"\u2022", alignment:AlignmentType.LEFT,
        style:{ paragraph:{ indent:{ left:560, hanging:280 } } } }]
    }]
  },
  sections:[
    { properties:{ page:{ size:{ width:12240, height:15840 }, margin:{ top:1440,right:1440,bottom:1440,left:1440 } } }, children:cover },
    { properties:pageProps, footers:{ default:makeFooter() }, children:[ ...p1, ...p2, ...p3, ...p4, ...p5 ] }
  ]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/home/claude/Luxora_Growth_Engine_Call_RevLeak.docx', buf);
  console.log('Done');
});

