  sp(0,10),
  inputTable("SHOW RATE", [
    ["Booked appointments per month", ""],
    ["% that actually show up", "Healthy: 80-90%"],
    ["Automated reminder system in place?", "72hr + 24hr + morning-of"],
    ["No-show follow-up protocol?", "Should fire within 2hrs"],
