{"returncode":0,"stdout":"const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, ImageRun,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
  PageNumber, Footer, PageBreak, TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

// ── Colors ───────────────────────────────────────────
const ROSE_DARK   = "6B2737";
const ROSE_MID    = "9E3F57";
const ROSE_LIGHT  = "F7EAED";
const GOLD        = "B8935A";
const CHARCOAL    = "2C2C2C";
const WARM_GRAY   = "F4F1F0";
const MID_GRAY    = "888888";
const WHITE       = "FFFFFF";
const BORDER_CLR  = "DDD0D4";

// ── Borders ──────────────────────────────────────────
const thinB    = { style: BorderStyle.SINGLE, size: 1, color: BORDER_CLR };
const allB     = { top: thinB, bottom: thinB, left: thinB, right: thinB };
const noB      = { style: BorderStyle.NONE,   size: 0, color: WHITE };
const noAll    = { top: noB, bottom: noB, left: noB, right: noB };
const leftRose = { top: noB, bottom: noB, right: noB, left: { style: BorderStyle.SINGLE, size: 20, color: ROSE_MID } };
const leftGold = { top: noB, bottom: noB, right: noB, left: { style: BorderStyle.SINGLE, size: 20, color: GOLD } };

// ── Helpers ──────────────────────────────────────────
function sp(b=40,a=40){ return new Paragraph({ spacing:{before:b,after:a}, children:[] }); }

function divider(color=ROSE_LIGHT){
  return new Paragraph({
    spacing:{before:60,after:60},
    border:{ bottom:{ style:BorderStyle.SINGLE, size:6, color, space:1 } },
    children:[]
  });
}

function pbBefore(){
  return new Paragraph({ pageBreakBefore:true, spacing:{before:0,after:0}, children:[] });
}

// ── Phase header ─────────────────────────────────────
function phaseHeader(num, label, subtitle){
  const isNum = num > 0;
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: noAll,
      shading:{ fill:ROSE_DARK, type:ShadingType.CLEAR },
      margins:{ top:140,bottom:140,left:360,right:360 },
      width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({
          spacing:{before:0,after:40},
          children:[
            ...(isNum ? [new TextRun({ text:`PHASE ${num}  `, font:"Arial", size:17, bold:true, color:GOLD, characterSpacing:120 })] : []),
            new TextRun({ text:label.toUpperCase(), font:"Arial", size:25, bold:true, color:WHITE, characterSpacing:80 })
          ]
        }),
        ...(subtitle ? [new Paragraph({
          spacing:{before:0,after:0},
          children:[new TextRun({ text:subtitle, font:"Arial", size:18, italics:true, color:"C8A8B0" })]
        })] : [])
      ]
    })] })]
  });
}

// ── Subsection label ─────────────────────────────────
function secLabel(text){
  return new Paragraph({
    spacing:{before:160,after:40},
    children:[new TextRun({ text:text.toUpperCase(), font:"Arial", size:17, bold:true, color:ROSE_MID, characterSpacing:80 })]
  });
}

// ── Revenue Leak module header ────────────────────────
function leakHeader(label){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: noAll,
      shading:{ fill:"3D1520", type:ShadingType.CLEAR },
      margins:{ top:100,bottom:100,left:320,right:320 },
      width:{ size:9360, type:WidthType.DXA },
      children:[new Paragraph({
        spacing:{before:0,after:0},
        children:[
          new TextRun({ text:"REVENUE LEAK SCAN  ", font:"Arial", size:16, bold:true, color:GOLD, characterSpacing:100 }),
          new TextRun({ text:label.toUpperCase(), font:"Arial", size:20, bold:true, color:WHITE })
        ]
      })]
    })] })]
  });
}

// ── What you say ─────────────────────────────────────
function say(text){
  return new Paragraph({
    spacing:{before:60,after:40},
    children:[new TextRun({ text, font:"Arial", size:22, color:CHARCOAL })]
  });
}

// ── Stage direction ──────────────────────────────────
function dir(text){
  return new Paragraph({
    spacing:{before:40,after:40},
    indent:{left:360},
    children:[new TextRun({ text, font:"Arial", size:18, italics:true, color:MID_GRAY })]
  });
}

// ── Question bullet ──────────────────────────────────
function q(text){
  return new Paragraph({
    spacing:{before:60,after:40},
    numbering:{ reference:"bullets", level:0 },
    children:[new TextRun({ text, font:"Arial", size:21, color:CHARCOAL })]
  });
}

// ── Input field row (for capturing her numbers) ──────
function inputRow(label, hint){
  return new TableRow({ children:[
    new TableCell({
      borders:allB,
      shading:{ fill:ROSE_LIGHT, type:ShadingType.CLEAR },
      margins:{top:80,bottom:80,left:140,right:140},
      width:{ size:4200, type:WidthType.DXA },
      children:[new Paragraph({ children:[new TextRun({ text:label, font:"Arial", size:19, bold:true, color:ROSE_DARK })] })]
    }),
    new TableCell({
      borders:allB,
      shading:{ fill:WHITE, type:ShadingType.CLEAR },
      margins:{top:80,bottom:80,left:140,right:140},
      width:{ size:2580, type:WidthType.DXA },
      children:[new Paragraph({ children:[new TextRun({ text:"_______________", font:"Arial", size:19, color:MID_GRAY })] })]
    }),
    new TableCell({
      borders:allB,
      shading:{ fill:WARM_GRAY, type:ShadingType.CLEAR },
      margins:{top:80,bottom:80,left:140,right:140},
      width:{ size:2580, type:WidthType.DXA },
      children:[new Paragraph({ children:[new TextRun({ text:hint, font:"Arial", size:17, italics:true, color:MID_GRAY })] })]
    })
  ]});
}

function inputTable(headerLabel, rows){
  const hRow = new TableRow({ children:[
    new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:140,right:140}, width:{size:4200,type:WidthType.DXA},
      children:[new Paragraph({ children:[new TextRun({ text:headerLabel, font:"Arial", size:17, bold:true, color:WHITE })] })] }),
    new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:140,right:140}, width:{size:2580,type:WidthType.DXA},
      children:[new Paragraph({ children:[new TextRun({ text:"HER ANSWER", font:"Arial", size:17, bold:true, color:WHITE })] })] }),
    new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:140,right:140}, width:{size:2580,type:WidthType.DXA},
      children:[new Paragraph({ children:[new TextRun({ text:"BENCHMARK", font:"Arial", size:17, bold:true, color:WHITE })] })] })
  ]});
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[4200,2580,2580],
    rows:[hRow, ...rows.map(r => inputRow(r[0], r[1]))]
  });
}

// ── Leak result callout ───────────────────────────────
function leakResult(label, calc, color=ROSE_LIGHT){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders:allB,
      shading:{ fill:color, type:ShadingType.CLEAR },
      margins:{top:100,bottom:100,left:220,right:220},
      width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({ spacing:{before:0,after:40}, children:[new TextRun({ text:"ESTIMATED LEAK:  ", font:"Arial", size:17, bold:true, color:ROSE_DARK, characterSpacing:60 }),
          new TextRun({ text:label, font:"Arial", size:17, bold:true, color:ROSE_DARK })] }),
        new Paragraph({ spacing:{before:0,after:0}, children:[new TextRun({ text:calc, font:"Arial", size:18, italics:true, color:CHARCOAL })] })
      ]
    })] })]
  });
}

// ── Callout box ──────────────────────────────────────
function callout(label, lines, bg=ROSE_LIGHT, lc=ROSE_DARK){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders:allB,
      shading:{ fill:bg, type:ShadingType.CLEAR },
      margins:{top:100,bottom:100,left:220,right:220},
      width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({ spacing:{before:0,after:60}, children:[new TextRun({ text:label.toUpperCase(), font:"Arial", size:17, bold:true, color:lc, characterSpacing:60 })] }),
        ...lines.map(l => new Paragraph({ spacing:{before:30,after:30}, children:[new TextRun({ text:l, font:"Arial", size:19, color:CHARCOAL })] }))
      ]
    })] })]
  });
}

// ── Left-accent block ────────────────────────────────
function accent(lines, gold=false){
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: gold ? leftGold : leftRose,
      shading:{ fill:WARM_GRAY, type:ShadingType.CLEAR },
      margins:{top:100,bottom:100,left:240,right:200},
      width:{ size:9360, type:WidthType.DXA },
      children: lines.map((l,i) => new Paragraph({
        spacing:{before:i===0?0:30,after:30},
        children:[new TextRun({ text:l, font:"Arial", size:20, italics:true, color:CHARCOAL })]
      }))
    })] })]
  });
}

// ── Pillar infographic ────────────────────────────────
const imgData = fs.readFileSync('/home/claude/pillars.png');
function pillarsImage(){
  return new Paragraph({
    spacing:{before:100,after:100},
    alignment:AlignmentType.CENTER,
    children:[new ImageRun({
      type:"png", data:imgData,
      transformation:{ width:624, height:416 },
      altText:{ title:"The Luxora 3 Pillars", description:"Market Blueprint, Acquisition Engine, Revenue Multiplier", name:"pillars" }
    })]
  });
}

// ── Pricing table ────────────────────────────────────
function priceTable(){
  function row(a,b,bg=WHITE){
    return new TableRow({ children:[
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:140,right:140}, width:{size:5400,type:WidthType.DXA},
        children:[new Paragraph({ children:[new TextRun({ text:a, font:"Arial", size:20, color:CHARCOAL })] })] }),
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:140,right:140}, width:{size:3960,type:WidthType.DXA},
        children:[new Paragraph({ children:[new TextRun({ text:b, font:"Arial", size:20, bold:true, color:ROSE_DARK })] })] })
    ]});
  }
  const hRow = new TableRow({ children:[
    new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:140,right:140}, width:{size:5400,type:WidthType.DXA},
      children:[new Paragraph({ children:[new TextRun({ text:"OPTION", font:"Arial", size:17, bold:true, color:WHITE })] })] }),
    new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:140,right:140}, width:{size:3960,type:WidthType.DXA},
      children:[new Paragraph({ children:[new TextRun({ text:"INVESTMENT", font:"Arial", size:17, bold:true, color:WHITE })] })] })
  ]});
  return new Table({
    width:{ size:9360, type:WidthType.DXA },
    columnWidths:[5400,3960],
    rows:[
      hRow,
      row("Paid in Full", "$9,000", ROSE_LIGHT),
      row("2-Pay", "$4,975 × 2", WHITE),
      row("Financing", "Klarna / Affirm", WARM_GRAY)
    ]
  });
}

function makeFooter(){
  return new Footer({ children:[new Paragraph({
    tabStops:[{ type:TabStopType.RIGHT, position:TabStopPosition.MAX }],
    children:[
      new TextRun({ text:"THE LUXORA COLLECTIVE  |  Growth Engine Discovery Call", font:"Arial", size:16, color:MID_GRAY }),
      new TextRun({ text:"\tPage ", font:"Arial", size:16, color:MID_GRAY }),
      new TextRun({ children:[PageNumber.CURRENT], font:"Arial", size:16, color:MID_GRAY })
    ]
  })] });
}

const pageProps = { page:{ size:{ width:12240, height:15840 }, margin:{ top:1080, right:1440, bottom:1080, left:1440 } } };

// ══════════════════════════════════════════════════════════
// COVER
// ══════════════════════════════════════════════════════════
const cover = [
  new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders:noAll, shading:{ fill:ROSE_DARK, type:ShadingType.CLEAR },
      margins:{top:600,bottom:600,left:720,right:720}, width:{size:9360,type:WidthType.DXA},
      children:[
        new Paragraph({ spacing:{before:0,after:40}, children:[new TextRun({ text:"THE LUXORA COLLECTIVE", font:"Arial", size:18, bold:true, color:"C8A8B0", characterSpacing:120 })] }),
        new Paragraph({ spacing:{before:0,after:120}, border:{ bottom:{ style:BorderStyle.SINGLE, size:4, color:GOLD, space:1 } }, children:[] }),
        new Paragraph({ spacing:{before:140,after:60}, children:[new TextRun({ text:"Growth Engine", font:"Arial", size:52, bold:true, color:WHITE })] }),
        new Paragraph({ spacing:{before:0,after:60}, children:[new TextRun({ text:"Discovery Call Script", font:"Arial", size:30, bold:true, color:WHITE })] }),
        new Paragraph({ spacing:{before:0,after:200}, children:[new TextRun({ text:"With Live Revenue Leak Scan", font:"Arial", size:22, color:GOLD, italics:true })] }),
        new Paragraph({ spacing:{before:0,after:40}, children:[new TextRun({ text:"This call has two jobs.", font:"Arial", size:21, bold:true, color:WHITE })] }),
        new Paragraph({ spacing:{before:0,after:40}, children:[new TextRun({ text:"First: make her feel more understood than she has ever felt on a business call.", font:"Arial", size:20, color:"C8A8B0" })] }),
        new Paragraph({ spacing:{before:0,after:60}, children:[new TextRun({ text:"Second: show her the exact dollar amount her business is losing, in real time, before you ever describe the solution.", font:"Arial", size:20, italics:true, color:GOLD })] }),
        new Paragraph({ spacing:{before:0,after:40}, children:[new TextRun({ text:"When she can see the number, the program is not a cost. It is the answer.", font:"Arial", size:20, color:"C8A8B0" })] }),
        new Paragraph({ spacing:{before:120,after:0}, border:{ bottom:{ style:BorderStyle.SINGLE, size:4, color:GOLD, space:1 } }, children:[] }),
        new Paragraph({ spacing:{before:100,after:20}, children:[new TextRun({ text:"Before every call: open revleak.theluxoracollective.co in a separate tab.", font:"Arial", size:18, bold:true, color:GOLD })] }),
        new Paragraph({ spacing:{before:0,after:80}, children:[new TextRun({ text:"You will run through the scan live with her during Phase 2. The numbers it generates are your transition into the pitch.", font:"Arial", size:18, color:"C8A8B0" })] }),
        new Paragraph({ spacing:{before:0,after:20}, children:[new TextRun({ text:"Bethany Anne  |  Co-Founder & CEO", font:"Arial", size:19, color:"C8A8B0" })] }),
        new Paragraph({ spacing:{before:0,after:0}, children:[new TextRun({ text:"theluxoracollective.co", font:"Arial", size:19, color:GOLD })] }),
      ]
    })] })]
  }),
  new Paragraph({ pageBreakBefore:true, spacing:{before:0,after:0}, children:[] })
];

// ══════════════════════════════════════════════════════════
// PHASE 1 — OPEN
// ══════════════════════════════════════════════════════════
const p1 = [
  phaseHeader(1, "Open", "60 seconds. Warm. Unhurried. She already feels different."),
  sp(0,20),
  say('"Hey [name], how\'s your week going so far?"'),
  dir("[They answer. Move forward.]"),
  say('"Nice. And where are you calling in from?"'),
  dir("[They answer. Move forward.]"),
  say('"Perfect. Alright, let\'s jump in."'),
  sp(0,10), divider(), sp(0,10),
  say('"So here\'s what I want to do today. I\'ve looked at your business before this call, so I have a solid picture already, but I have deeper questions.'),
  sp(0,20),
  say('My goal is simple: I want to genuinely understand what is going on, where you feel stuck, and whether there is actually an opportunity for us to help. If there is, I\'ll walk you through exactly what that looks like. If not, I\'ll point you in the right direction either way.'),
  sp(0,20),
  say('Sound fair?"'),
  dir("[Wait for yes. Let the silence land.]"),
  sp(0,10), divider(), sp(0,10),
  say('"Good. Before I ask you anything specific, I want to hear it in your own words.'),
  sp(0,20),
  say('What\'s going on in your business right now that made you reach out?"'),
  dir("[Let her talk. Do not interrupt. Write down her exact words. You will mirror them back in Phase 3.]"),
  sp(0,20),
  callout("Context questions to follow her answer", [
    '"Walk me through your business right now. What does a typical week look like for you?"',
    '"Where are you at revenue-wise right now, roughly?"',
    '"How long have you been at this level?"',
    '"What have you tried so far to grow it or fix what is not working?"',
  ], WARM_GRAY, ROSE_DARK),
  sp(0,20),
  secLabel("Emotional deep dive — go here before the scan"),
  say('"Let me ask you something a little different.'),
  sp(0,20),
  say('What\'s been weighing on you the most in the business lately?"'),
  dir("[Pause. Let her answer fully. Do not rush. Write down her exact words.]"),
  sp(0,20),
  q('"Where do you feel the most stuck right now?"'),
  q('"What is frustrating you that you feel like you should have figured out by now?"'),
  q('"What is not working, even though on the outside it might look like it is?"'),
  q('"If nothing changes, where do you realistically see this business a year from now?"'),
  q('"What would it mean for you personally if this business finally ran without you being the bottleneck?"'),
  dir("[Write down her exact words here. You will mirror them back in Phase 3. These words are your close.]"),
];

// ══════════════════════════════════════════════════════════
// PHASE 2 — REVENUE LEAK SCAN (the discovery spine)
// ══════════════════════════════════════════════════════════
const p2 = [
  pbBefore(),
  phaseHeader(2, "Revenue Leak Scan", "~25 minutes. Run this live with her. Her numbers are your transition into the pitch."),
  sp(0,20),
  accent([
    "Before this call: open revleak.theluxoracollective.co in a separate tab.",
    "You are going to run through this scan together, live, using her real numbers.",
    "Do not rush. Each section builds the case. By the end, she has seen her own revenue leak in dollars.",
    "That number becomes your close."
  ]),
  sp(0,20),
  say('"I want to try something a little different with you today, if you\'re open to it.'),
  sp(0,20),
  say('We built a tool called the Revenue Leak Scan. It takes about 25 minutes and it shows you, based on your actual numbers, exactly where your business is losing money and how much.'),
  sp(0,20),
  say('Most owners have never seen this laid out this clearly. And it changes the conversation completely.'),
  sp(0,20),
  say('Can I walk you through it right now?"'),
  dir("[Wait for yes. Pull up revleak.theluxoracollective.co.]"),
  sp(0,20),

  // ── MODULE 1: Booking Conversion ─────────────────
  leakHeader("Module 1: Booking Conversion"),
  sp(0,10),
  say('"Let\'s start with how leads become bookings. I want to ask you a few specific questions and we\'ll plug them in together."'),
  sp(0,10),
  inputTable("BOOKING CONVERSION", [
    ["Monthly website or inquiry leads", "Industry avg: 100-300/mo"],
    ["% that actually book an appointment", "Healthy: 40-60%"],
    ["Primary booking method (phone/online/DM)", "Online = lower drop-off"],
    ["Automated booking confirmation sent?", "Should fire within 5 min"],
  ]),
  sp(0,10),
  dir("[Enter her numbers into the scan. Let her see the booking conversion rate populate.]"),
  leakResult(
    "Booking Conversion Gap",
    "If she has 150 leads/month and books 30%, that is 90 unbooked leads. At $200 avg visit: up to $18,000/month walking out the door."
  ),
  sp(0,20),

  // ── MODULE 2: Show Rate ───────────────────────────
  leakHeader("Module 2: Show Rate"),
  sp(0,10),
  say('"Now let\'s look at what happens between booking and arrival."'),
  sp(0,10),
  inputTable("SHOW RATE", [
    ["Booked appointments per month", ""],
    ["% that actually show up", "Healthy: 80-90%"],
    ["Automated reminder system in place?", "72hr + 24hr + morning-of"],
    ["No-show follow-up protocol?", "Should fire within 2hrs"],
  ]),
  sp(0,10),
  dir("[Enter her numbers. Let the no-show cost populate on screen.]"),
  leakResult(
    "No-Show Revenue Loss",
    "At 25% no-show rate on 80 monthly appointments, that is 20 empty chairs. At $250/visit: $5,000/month in lost revenue. Fixable in 2 weeks."
  ),
  sp(0,10),
  say('"Here\'s what that number means. Every single one of those is a fixable problem. Not a marketing problem. An automation problem."'),
  sp(0,20),

  // ── MODULE 3: Consultation Conversion ────────────
  leakHeader("Module 3: Consultation Conversion"),
  sp(0,10),
  say('"Now let\'s look at what happens when they actually show up."'),
  sp(0,10),
  inputTable("CONSULTATION CONVERSION", [
    ["Clients who come in for first visit", ""],
    ["% who purchase a plan or package", "Healthy: 50-70%"],
    ["Does your team have a consultation script?", "Most do not"],
    ["Is a membership offered at every visit?", "Should be: always"],
  ]),
  sp(0,10),
  dir("[Enter her numbers.]"),
  leakResult(
    "Consultation Revenue Gap",
    "If 60 clients visit monthly and only 30% commit to a plan, that is 42 clients leaving without a pathway. Even converting 10 more per month at $500 avg plan = $5,000/month."
  ),
  sp(0,20),

  // ── MODULE 4: Retention + Lifetime Value ─────────
  leakHeader("Module 4: Retention + Lifetime Value"),
  sp(0,10),
  say('"This is usually where the biggest number lives."'),
  sp(0,10),
  inputTable("RETENTION + LTV", [
    ["How many clients came in once and never returned?", "Should be under 20%"],
    ["Average number of visits per client per year", "Healthy: 4-6"],
    ["Active membership or loyalty program?", "Strongest retention lever"],
    ["Automated re-book or follow-up sequence?", "Should fire at 21 days"],
  ]),
  sp(0,10),
  dir("[Enter her numbers. Let the LTV gap populate.]"),
