const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, ImageRun,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
  PageNumber, Footer, PageBreak, TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

// ── Colors ───────────────────────────────────────────
const ROSE_DARK   = "6B2737";
const ROSE_MID    = "9E3F57";
const ROSE_LIGHT  = "F7EAED";
const GOLD        = "B8935A";
const CHARCOAL    = "2C2C2C";
const WARM_GRAY   = "F4F1F0";
const MID_GRAY    = "888888";
const WHITE       = "FFFFFF";
const BORDER_CLR  = "DDD0D4";
const DEEP_DARK   = "3D1520";

// ── Borders ──────────────────────────────────────────
const thinB    = { style: BorderStyle.SINGLE, size: 1, color: BORDER_CLR };
const allB     = { top: thinB, bottom: thinB, left: thinB, right: thinB };
const noB      = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noAll    = { top: noB, bottom: noB, left: noB, right: noB };
const leftRose = { top: noB, bottom: noB, right: noB, left: { style: BorderStyle.SINGLE, size: 20, color: ROSE_MID } };
const leftGold = { top: noB, bottom: noB, right: noB, left: { style: BorderStyle.SINGLE, size: 20, color: GOLD } };

// ── Core helpers ─────────────────────────────────────
function sp(b=40, a=40){ return new Paragraph({ spacing:{before:b,after:a}, children:[] }); }

function divider(color=ROSE_LIGHT){
  return new Paragraph({
    spacing:{before:60,after:60},
    border:{ bottom:{ style:BorderStyle.SINGLE, size:6, color, space:1 } },
    children:[]
  });
}

function pbBefore(){
  return new Paragraph({ pageBreakBefore:true, spacing:{before:0,after:0}, children:[] });
}

// ── Phase header band ─────────────────────────────────
function phaseHeader(num, label, timeHint, subtitle){
  return new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: noAll,
      shading:{ fill:ROSE_DARK, type:ShadingType.CLEAR },
      margins:{ top:140, bottom:140, left:360, right:360 },
      width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({
          spacing:{before:0,after:40},
          children:[
            ...(num > 0 ? [new TextRun({ text:`PHASE ${num}  `, font:"Arial", size:17, bold:true, color:GOLD, characterSpacing:120 })] : []),
            new TextRun({ text:label.toUpperCase(), font:"Arial", size:25, bold:true, color:WHITE, characterSpacing:80 }),
            ...(timeHint ? [new TextRun({ text:`   ${timeHint}`, font:"Arial", size:17, bold:false, color:"C8A8B0" })] : [])
          ]
        }),
        ...(subtitle ? [new Paragraph({
          spacing:{before:0,after:0},
          children:[new TextRun({ text:subtitle, font:"Arial", size:18, italics:true, color:"C8A8B0" })]
        })] : [])
      ]
    })] })]
  });
}

// ── Time budget strip ─────────────────────────────────
function timeBudget(text){
  return new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: noAll,
      shading:{ fill:DEEP_DARK, type:ShadingType.CLEAR },
      margins:{ top:60, bottom:60, left:240, right:240 },
      width:{ size:9360, type:WidthType.DXA },
      children:[new Paragraph({
        spacing:{before:0,after:0},
        children:[new TextRun({ text:`⏱  ${text}`, font:"Arial", size:17, bold:true, color:GOLD })]
      })]
    })] })]
  });
}

// ── Revenue Leak module header ────────────────────────
function leakHeader(label){
  return new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: noAll,
      shading:{ fill:DEEP_DARK, type:ShadingType.CLEAR },
      margins:{ top:100, bottom:100, left:320, right:320 },
      width:{ size:9360, type:WidthType.DXA },
      children:[new Paragraph({
        spacing:{before:0,after:0},
        children:[
          new TextRun({ text:"REVENUE LEAK  ", font:"Arial", size:15, bold:true, color:GOLD, characterSpacing:100 }),
          new TextRun({ text:label.toUpperCase(), font:"Arial", size:20, bold:true, color:WHITE })
        ]
      })]
    })] })]
  });
}

// ── What you say — large, readable ───────────────────
function say(text){
  return new Paragraph({
    spacing:{before:60,after:40},
    children:[new TextRun({ text, font:"Arial", size:22, color:CHARCOAL })]
  });
}

// ── Pause cue — makes breath space visible on page ───
function pause(text){
  return new Paragraph({
    spacing:{before:40,after:40},
    indent:{left:360},
    children:[new TextRun({ text:`[PAUSE  —  ${text}]`, font:"Arial", size:18, bold:true, italics:true, color:ROSE_MID })]
  });
}

// ── Stage direction — italic gray ────────────────────
function dir(text){
  return new Paragraph({
    spacing:{before:40,after:40},
    indent:{left:360},
    children:[new TextRun({ text, font:"Arial", size:18, italics:true, color:MID_GRAY })]
  });
}

// ── Single discovery question with space to breathe ──
function q(text, followPause){
  const items = [
    new Paragraph({
      spacing:{before:80,after:40},
      numbering:{ reference:"bullets", level:0 },
      children:[new TextRun({ text, font:"Arial", size:21, color:CHARCOAL })]
    })
  ];
  if(followPause){
    items.push(new Paragraph({
      spacing:{before:0,after:40},
      indent:{left:560},
      children:[new TextRun({ text:`[${followPause}]`, font:"Arial", size:17, italics:true, color:ROSE_MID })]
    }));
  }
  return items;
}

// ── Callout box ──────────────────────────────────────
function callout(label, lines, bg=ROSE_LIGHT, lc=ROSE_DARK){
  return new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: allB,
      shading:{ fill:bg, type:ShadingType.CLEAR },
      margins:{ top:100, bottom:100, left:220, right:220 },
      width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({ spacing:{before:0,after:60}, children:[new TextRun({ text:label.toUpperCase(), font:"Arial", size:17, bold:true, color:lc, characterSpacing:60 })] }),
        ...lines.map(l => new Paragraph({ spacing:{before:30,after:30}, children:[new TextRun({ text:l, font:"Arial", size:19, color:CHARCOAL })] }))
      ]
    })] })]
  });
}

// ── Left-accent principle block ───────────────────────
function accent(lines, gold=false){
  return new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: gold ? leftGold : leftRose,
      shading:{ fill:WARM_GRAY, type:ShadingType.CLEAR },
      margins:{ top:100, bottom:100, left:240, right:200 },
      width:{ size:9360, type:WidthType.DXA },
      children: lines.map((l,i) => new Paragraph({
        spacing:{before:i===0?0:30,after:30},
        children:[new TextRun({ text:l, font:"Arial", size:20, italics:true, color:CHARCOAL })]
      }))
    })] })]
  });
}

// ── Input capture table for scan ─────────────────────
function inputTable(headerLabel, rows){
  const hRow = new TableRow({ children:[
    new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:70,bottom:70,left:140,right:140}, width:{size:4200,type:WidthType.DXA},
      children:[new Paragraph({ children:[new TextRun({ text:headerLabel, font:"Arial", size:17, bold:true, color:WHITE })] })] }),
    new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:70,bottom:70,left:140,right:140}, width:{size:2580,type:WidthType.DXA},
      children:[new Paragraph({ children:[new TextRun({ text:"HER ANSWER", font:"Arial", size:17, bold:true, color:WHITE })] })] }),
    new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:70,bottom:70,left:140,right:140}, width:{size:2580,type:WidthType.DXA},
      children:[new Paragraph({ children:[new TextRun({ text:"BENCHMARK", font:"Arial", size:17, bold:true, color:WHITE })] })] })
  ]});
  const dataRows = rows.map(r => new TableRow({ children:[
    new TableCell({ borders:allB, shading:{fill:ROSE_LIGHT,type:ShadingType.CLEAR}, margins:{top:70,bottom:70,left:140,right:140}, width:{size:4200,type:WidthType.DXA},
      children:[new Paragraph({ children:[new TextRun({ text:r[0], font:"Arial", size:18, bold:true, color:ROSE_DARK })] })] }),
    new TableCell({ borders:allB, shading:{fill:WHITE,type:ShadingType.CLEAR}, margins:{top:70,bottom:70,left:140,right:140}, width:{size:2580,type:WidthType.DXA},
      children:[new Paragraph({ children:[new TextRun({ text:"_______________", font:"Arial", size:18, color:MID_GRAY })] })] }),
    new TableCell({ borders:allB, shading:{fill:WARM_GRAY,type:ShadingType.CLEAR}, margins:{top:70,bottom:70,left:140,right:140}, width:{size:2580,type:WidthType.DXA},
      children:[new Paragraph({ children:[new TextRun({ text:r[1], font:"Arial", size:17, italics:true, color:MID_GRAY })] })] })
  ]}));
  return new Table({ width:{ size:9360, type:WidthType.DXA }, columnWidths:[4200,2580,2580], rows:[hRow,...dataRows] });
}

// ── Leak result ───────────────────────────────────────
function leakResult(label, calc){
  return new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: allB,
      shading:{ fill:ROSE_LIGHT, type:ShadingType.CLEAR },
      margins:{ top:100, bottom:100, left:220, right:220 },
      width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({ spacing:{before:0,after:40}, children:[
          new TextRun({ text:"ESTIMATED LEAK:  ", font:"Arial", size:17, bold:true, color:ROSE_DARK, characterSpacing:60 }),
          new TextRun({ text:label, font:"Arial", size:17, bold:true, color:ROSE_DARK })
        ]}),
        new Paragraph({ spacing:{before:0,after:0}, children:[new TextRun({ text:calc, font:"Arial", size:18, italics:true, color:CHARCOAL })] })
      ]
    })] })]
  });
}

// ── Total leak box ────────────────────────────────────
function totalLeakBox(){
  return new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: allB,
      shading:{ fill:DEEP_DARK, type:ShadingType.CLEAR },
      margins:{ top:160, bottom:160, left:280, right:280 },
      width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({ spacing:{before:0,after:80}, children:[new TextRun({ text:"TOTAL ESTIMATED ANNUAL REVENUE LEAK", font:"Arial", size:19, bold:true, color:GOLD, characterSpacing:60 })] }),
        new Paragraph({ spacing:{before:0,after:80}, children:[new TextRun({ text:"Write her total here:", font:"Arial", size:19, color:WHITE })] }),
        new Paragraph({ spacing:{before:0,after:80}, children:[new TextRun({ text:"$________________________ per year", font:"Arial", size:26, bold:true, color:WHITE })] }),
        new Paragraph({ spacing:{before:0,after:0}, children:[new TextRun({ text:"This number is the spine of your transition, your pitch, and your close.", font:"Arial", size:17, italics:true, color:"C8A8B0" })] })
      ]
    })] })]
  });
}

// ── Pricing table ─────────────────────────────────────
function priceTable(){
  function row(a,b,bg=WHITE){
    return new TableRow({ children:[
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:140,right:140}, width:{size:5400,type:WidthType.DXA},
        children:[new Paragraph({ children:[new TextRun({ text:a, font:"Arial", size:20, color:CHARCOAL })] })] }),
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:140,right:140}, width:{size:3960,type:WidthType.DXA},
        children:[new Paragraph({ children:[new TextRun({ text:b, font:"Arial", size:20, bold:true, color:ROSE_DARK })] })] })
    ]});
  }
  return new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[5400,3960],
    rows:[
      new TableRow({ children:[
        new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:140,right:140}, width:{size:5400,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:"OPTION", font:"Arial", size:17, bold:true, color:WHITE })] })] }),
        new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:140,right:140}, width:{size:3960,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:"INVESTMENT", font:"Arial", size:17, bold:true, color:WHITE })] })] })
      ]}),
      row("Paid in Full", "$9,000", ROSE_LIGHT),
      row("2-Pay", "$4,975 × 2", WHITE),
      row("Financing", "Klarna / Affirm", WARM_GRAY)
    ]
  });
}

// ── Pillar image ──────────────────────────────────────
const imgData = fs.readFileSync('/home/claude/pillars.png');
function pillarsImage(){
  return new Paragraph({
    spacing:{before:80,after:80}, alignment:AlignmentType.CENTER,
    children:[new ImageRun({
      type:"png", data:imgData, transformation:{ width:624, height:416 },
      altText:{ title:"The Luxora 3 Pillars", description:"Market Blueprint, Acquisition Engine, Revenue Multiplier", name:"pillars" }
    })]
  });
}

function makeFooter(){
  return new Footer({ children:[new Paragraph({
    tabStops:[{ type:TabStopType.RIGHT, position:TabStopPosition.MAX }],
    children:[
      new TextRun({ text:"THE LUXORA COLLECTIVE  |  Growth Engine Discovery Call", font:"Arial", size:16, color:MID_GRAY }),
      new TextRun({ text:"\tPage ", font:"Arial", size:16, color:MID_GRAY }),
      new TextRun({ children:[PageNumber.CURRENT], font:"Arial", size:16, color:MID_GRAY })
    ]
  })] });
}

const pageProps = { page:{ size:{ width:12240, height:15840 }, margin:{ top:1080, right:1440, bottom:1080, left:1440 } } };

// ══════════════════════════════════════════════════════════════
// COVER
// ══════════════════════════════════════════════════════════════
const cover = [
  new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: noAll, shading:{ fill:ROSE_DARK, type:ShadingType.CLEAR },
      margins:{ top:600, bottom:600, left:720, right:720 }, width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({ spacing:{before:0,after:40}, children:[new TextRun({ text:"THE LUXORA COLLECTIVE", font:"Arial", size:18, bold:true, color:"C8A8B0", characterSpacing:120 })] }),
        new Paragraph({ spacing:{before:0,after:120}, border:{ bottom:{ style:BorderStyle.SINGLE, size:4, color:GOLD, space:1 } }, children:[] }),
        new Paragraph({ spacing:{before:140,after:60}, children:[new TextRun({ text:"Growth Engine", font:"Arial", size:52, bold:true, color:WHITE })] }),
        new Paragraph({ spacing:{before:0,after:60}, children:[new TextRun({ text:"Discovery Call Script", font:"Arial", size:30, bold:true, color:WHITE })] }),
        new Paragraph({ spacing:{before:0,after:200}, children:[new TextRun({ text:"With Live Revenue Leak Scan", font:"Arial", size:22, color:GOLD, italics:true })] }),
        new Paragraph({ spacing:{before:0,after:40}, children:[new TextRun({ text:"This call has two jobs.", font:"Arial", size:21, bold:true, color:WHITE })] }),
        new Paragraph({ spacing:{before:0,after:40}, children:[new TextRun({ text:"First: make her feel more understood than she has ever felt on a business call.", font:"Arial", size:20, color:"C8A8B0" })] }),
        new Paragraph({ spacing:{before:0,after:60}, children:[new TextRun({ text:"Second: show her the exact dollar amount her business is losing, in real time, before you ever describe the solution.", font:"Arial", size:20, italics:true, color:GOLD })] }),
        new Paragraph({ spacing:{before:0,after:60}, children:[new TextRun({ text:"When she can see her number, the program is not a cost. It is the obvious answer.", font:"Arial", size:20, color:"C8A8B0" })] }),
        new Paragraph({ spacing:{before:120,after:0}, border:{ bottom:{ style:BorderStyle.SINGLE, size:4, color:GOLD, space:1 } }, children:[] }),
        new Paragraph({ spacing:{before:100,after:20}, children:[new TextRun({ text:"Total call time: 45 to 60 minutes.", font:"Arial", size:19, bold:true, color:WHITE })] }),
        new Paragraph({ spacing:{before:0,after:40}, children:[new TextRun({ text:"Open revleak.theluxoracollective.co in a tab before you dial.", font:"Arial", size:18, color:GOLD })] }),
        new Paragraph({ spacing:{before:0,after:20}, children:[new TextRun({ text:"Bethany Anne  |  Co-Founder & CEO", font:"Arial", size:19, color:"C8A8B0" })] }),
        new Paragraph({ spacing:{before:0,after:0}, children:[new TextRun({ text:"theluxoracollective.co", font:"Arial", size:19, color:GOLD })] }),
      ]
    })] })]
  }),
  new Paragraph({ pageBreakBefore:true, spacing:{before:0,after:0}, children:[] })
];

// ══════════════════════════════════════════════════════════════
// BEFORE YOU DIAL — PRINCIPLES
// ══════════════════════════════════════════════════════════════
const principles = [
  phaseHeader(0, "Before You Dial", "", "Read these. Internalize them. Then put this page down and make the call."),
  sp(0,20),
  timeBudget("Total call: 45-60 min  |  Open: 5 min  |  Emotional: 8 min  |  Scan: 20 min  |  Mirror: 5 min  |  Pitch + Close: 15 min"),
  sp(0,20),
  accent([
    "The scan does the logic work. Your job is to do the emotional work.",
    "She has to feel seen before she can be sold. In that order. Never reversed.",
    "If you rush to the numbers, you lose the trust. If you earn the trust first, the numbers close her."
  ]),
  sp(0,20),
  accent([
    "Slow is the strategy. Every pause you hold is proof that you are different from every other call she has taken.",
    "You are not performing confidence. You are being the most grounded person she has talked to about her business.",
    "That groundedness is what she is buying."
  ], true),
  sp(0,20),
  callout("The sentence that wins every call", [
    "You do not say: 'So let me tell you about our program.'",
    "You say: 'We just found [HER TOTAL] leaking from your business. Here is exactly how we close those gaps.'",
    "",
    "The scan earns the pitch. The pitch is just the answer to a question she is already asking."
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,20),
  callout("The three things that make a Luxora call different", [
    "1.  You already have her numbers loaded before she knows you have them. That is instant credibility.",
    "2.  You ask one emotional question and then go completely quiet. Most salespeople cannot do that.",
    "3.  You mirror her exact words back. Not your summary. Her words. That is when the lock happens."
  ], WARM_GRAY, ROSE_DARK),
  sp(0,20),
  divider(),
];

// ══════════════════════════════════════════════════════════════
// PHASE 1 — OPEN  (5 minutes)
// ══════════════════════════════════════════════════════════════
const p1 = [
  phaseHeader(1, "Open", "(5 min)", "Set safety. She needs to feel different about this call in the first 60 seconds."),
  sp(0,20),

  say('"Hey [name], how\'s your week going so far?"'),
  dir("[She answers. Do not rush through rapport. Two or three genuine sentences.]"),
  say('"Nice. And where are you calling in from today?"'),
  dir("[She answers. Move forward.]"),
  sp(0,10), divider(), sp(0,10),

  say('"Before we dive in, I want to be upfront with you about something.'),
  sp(0,20),
  say('This is not a sales call for me. My goal today is to genuinely understand what is going on in your business and figure out whether we can actually help.'),
  sp(0,20),
  say('If I think we can, I will show you exactly what that looks like. If I do not think we are the right fit, I will tell you that honestly and point you somewhere better.'),
  sp(0,20),
  say('Sound fair?"'),
  pause("Wait for yes. Let the silence land. She already feels safer than she did on any other call today."),
  sp(0,10), divider(), sp(0,10),

  say('"Good. So before I ask you anything specific, I just want to hear it from you.'),
  sp(0,20),
  say('What\'s going on in your business right now that made you reach out?"'),
  pause("She talks. You write. Do not interrupt. Her exact words are your close."),
  sp(0,20),

  callout("Context questions — follow the thread of what she just said", [
    '"Walk me through a typical week right now. What does that look like for you?"',
    '"Where are you at revenue-wise, roughly?"',
    '"How long have you been at this level?"',
    '"What have you tried so far to grow it or fix what is not working?"',
  ], WARM_GRAY, ROSE_DARK),
];

// ══════════════════════════════════════════════════════════════
// PHASE 2 — EMOTIONAL DEEP DIVE  (8 minutes)
// ══════════════════════════════════════════════════════════════
const p2 = [
  pbBefore(),
  phaseHeader(2, "Emotional Deep Dive", "(8 min)", "One question at a time. Full silence after each. This is the most important 8 minutes of the call."),
  sp(0,20),
  accent([
    "Do not ask these as a list. Ask one. Stop. Let her answer fully. Then ask the next.",
    "The pause after each answer is where trust is built. Hold it even when it feels uncomfortable.",
    "Write her exact words in the margin. You will use them word-for-word in Phase 4."
  ]),
  sp(0,20),

  say('"Let me ask you something a little different.'),
  sp(0,20),
  say('What has been weighing on you the most in the business lately?"'),
  pause("Full stop. Let her go as deep as she wants. Do not rescue her from the silence."),
  sp(0,20),

  say('"And where do you feel the most stuck right now?"'),
