    "When you mirror them back in Phase 4, she will say 'yes, exactly.' That is the moment trust becomes commitment.",
    "Do not move to the scan until she has fully answered. There is no rush. The scan will still be there."
  ], true),
];

// ══════════════════════════════════════════════════════════════
// PHASE 3 — REVENUE LEAK SCAN  (20 minutes)
// ══════════════════════════════════════════════════════════════
const p3 = [
  pbBefore(),
  phaseHeader(3, "Revenue Leak Scan", "(20 min)", "Run this live together. Her numbers build the case. The total is your transition into the pitch."),
  sp(0,20),
  accent([
    "Before this call: open revleak.theluxoracollective.co in a separate tab. Have it ready.",
