  say('"So I want to connect what we just saw in the numbers to what you told me at the beginning of this call.'),
  sp(0,20),
  say('Because I think they are telling the same story.'),
  sp(0,20),
  say('You said [USE HER EXACT WORDS FROM PHASE 2].'),
  sp(0,20),
  say('And what we just found in the scan is exactly why that feeling is real. It is not in your head. It is in your system.'),
  sp(0,20),
  say('The business has been leaking quietly, in five specific places, and nobody ever showed you where.'),
  sp(0,20),
  say('Is that close to what you have been experiencing?"'),
  pause("Let her confirm. That moment is when trust becomes commitment. Do not fill the silence."),
  sp(0,20),
  divider(),
  sp(0,10),

  say('"Here is what I see in the clinics that get past this.'),
  sp(0,20),
  say('They are not doing more. They are not spending more on ads. They are not grinding harder.'),
  sp(0,20),
  say('They closed the five gaps. And once they did, the business stopped feeling like something they were holding together with their hands.'),
  sp(0,20),
  say('It started running. The owner got her time back. And the revenue got predictable.'),
  sp(0,20),
  say('That is what a system does. And that is what you do not have yet. Not because you are not capable. Because no one ever built it with you."'),
  pause("Let that land. She is seeing herself in that version right now. The pause is the pivot."),
  sp(0,20),

  // ── Qualify before pitching ────────────────────────
  callout("Two qualification questions — ask these before you move to the pitch", [
    '"Do you make decisions like this on your own, or does anyone else need to be part of this conversation?"',
    "",
    '"If you were going to fix this, when would you want that to happen? What would make now the right time?"',
    "",
    "[Get a name if there is someone else. Get urgency before you pitch. Without both of these, you are pitching into the air.]"
  ], WARM_GRAY, ROSE_DARK),
];

// ══════════════════════════════════════════════════════════════
// PHASE 5 — THE PITCH  (8 minutes)
// ══════════════════════════════════════════════════════════════
const p5 = [
  pbBefore(),
  phaseHeader(5, "The Pitch", "(8 min)", "Ask permission first. Every pillar ties back to a specific leak you found together."),
  sp(0,20),

  say('"Based on everything we just went through, I do see a real and specific path forward here.'),
  sp(0,20),
  say('The revenue is already in your business. We just need to close the gaps and put the system underneath it.'),
  sp(0,20),
  say('Can I show you exactly how we do that?"'),
  pause("Wait for yes. The yes matters. Do not pitch without it."),
  sp(0,20),

  new Paragraph({ spacing:{before:0,after:40}, children:[new TextRun({ text:"OUR 3 PILLARS", font:"Arial", size:20, bold:true, color:ROSE_DARK, characterSpacing:100 })] }),
  pillarsImage(),
  sp(0,10),

  say('"Pillar One is the Market Blueprint.'),
  sp(0,20),
  say('Before we run a single ad, we map your entire market. Competitors, pricing, gaps, what is working in your area. Within 72 hours you know exactly where your opportunity is before you spend a dollar.'),
  sp(0,20),
  say('This is what fixes your booking conversion gap. Because you stop guessing and start targeting."'),
  dir("Check-in: \"Does that already feel different from what you have seen before?\""),
  sp(0,20),

  say('"Pillar Two is the Acquisition Engine.'),
  sp(0,20),
  say('We install the entire system. Ads, AI follow-up, CRM, booking automation, front desk scripts. All of it built so your team can execute without you holding it together.'),
  sp(0,20),
  say('This is what closes your show rate leak and your consultation conversion gap. The reminders go out automatically. The scripts are in the hands of your team. You are not the bottleneck anymore."'),
  dir("Check-in: \"Can you see how this solves what we found in the scan?\""),
  sp(0,20),

  say('"Pillar Three is the Revenue Multiplier.'),
  sp(0,20),
  say('This is where we capture the retention leak. The one with the biggest number.'),
  sp(0,20),
  say('Memberships, packages, sales training, re-book sequences, referral systems. Every client becomes $1,800 to $10,000 in lifetime value instead of a one-time visit that walked out the door."'),
  dir("Check-in: \"Is this the piece that has been missing?\""),
  sp(0,20),

  callout("Tie everything back to her number before you move to delivery", [
    '"We found [HER TOTAL] leaking from your business.',
    "The Growth Engine is built to close those exact gaps, starting in the first 30 days.",
    "By Month 3, the program has typically recovered more than it cost, from revenue that was already in your pipeline.",
    "We are not adding anything new. We are recovering what is already yours."
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,20),

  callout("Temperature check — do this before delivery", [
    '"How are you feeling about all of this right now?"',
    "",
    "If anything less than engaged: \"What part of this is not landing clearly yet?\"",
    "Address it before you say another word about the program."
  ], WARM_GRAY, ROSE_DARK),
  sp(0,20),

  say('"We partner for 90 days. We build and install everything with you. Not theory. Not a course. Not homework.'),
  sp(0,20),
  say('Bi-weekly strategy calls, full system build-out, team training, and ongoing optimization. Most clients continue after the 90 days. But that is entirely your choice."'),
];

// ══════════════════════════════════════════════════════════════
// PHASE 6 — PRICE + CLOSE  (7 minutes)
// ══════════════════════════════════════════════════════════════
const p6 = [
  pbBefore(),
  phaseHeader(6, "Price + Close", "(7 min)", "State it clearly. Stop talking. The silence is the close."),
  sp(0,20),

  say('"To build and install The Luxora Growth Engine over the next 90 days, the investment is:"'),
  sp(0,20),
  priceTable(),
  sp(0,20),
  pause("Stop talking. Do not explain the price. Do not add anything. Let it sit."),
  sp(0,20),

  say('"And I want to say one more thing before you respond.'),
  sp(0,20),
  say('If we do not generate at least two times your investment in recovered lifetime client value within 90 days, we keep working with you at no additional cost until we do.'),
  sp(0,20),
  say('As long as you follow the system, we do not stop until the number is there.'),
  sp(0,20),
  say('No agency can offer that because they do not own the whole engine. We do."'),
  pause("Let the guarantee land before you ask the close question. At least three full seconds."),
  sp(0,20),

  say('"Based on everything we have been through today, and the number we found together, do you feel like this is something you are ready to fix right now, or are you still more in the figuring-it-out phase?"'),
  pause("Two honest options. No pressure. No fake urgency. Her answer tells you exactly where you are."),
  sp(0,20),
  divider(),
  sp(0,20),

  callout("If she says yes:", [
    '"Perfect. I am going to pull up our checkout page and walk you through it right now. It takes two minutes."',
    "",
    "go.theluxoracollective.co/the-luxora-growth-engine",
    "",
    "[Stay on the call. Walk her through every field. Do not send the link and let her go alone.]",
    "[Screen share if on video. If she is on mobile, stay quiet while she navigates. Silence is fine. Do not rush.]"
  ], ROSE_LIGHT, GOLD),
  sp(0,20),

  callout("If she hesitates:", [
    '"That is completely okay. Can I ask what is making you feel like you are still in figuring-it-out mode?"',
    "",
    "[Full stop. Let her tell you the real objection. Do not guess it. Mirror it back. Reframe it. Then close again with the same question.]"
  ], WARM_GRAY, ROSE_DARK),
  sp(0,20),

  callout("If she says 'I need to think about it':", [
    '"Of course. What would make this a clear yes for you?"',
    "",
    "She will tell you. Common answers:",
    "  Cost concern: reference the scan total directly. $9,000 against [HER TOTAL] leaking is not a cost. It is a recovery.",
    "  Needs a partner: get the name. Schedule a call with both of them this week, not in two weeks.",
    "  Timing: 'What would need to change for the timing to feel right?' Then solve for that specifically."
  ], WARM_GRAY, ROSE_DARK),
  sp(0,20),

  callout("If she says 'we already tried ads':", [
    '"That is exactly why we start with the system before we ever touch ads.',
    "We just showed you five places where your business is leaking. Running ads into those five open gaps does not grow the business.",
    "It just fills a leaky bucket faster.",
    "We close the gaps first. Then we add the fuel. Every time. In that order."
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,20),

  callout("If she says 'the investment is too much':", [
    "Do not defend the price. Reference her number.",
    "",
    '"We found [HER TOTAL] leaving your business every year.',
    "The program is $9,000.",
    "You are not spending $9,000. You are recovering a multiple of $9,000 that is already in your pipeline, from clients you already have.",
    "The real question is what it costs to leave that on the table for another year."
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,20),

  divider(GOLD),
  new Paragraph({ spacing:{before:80,after:40}, alignment:AlignmentType.CENTER, children:[new TextRun({ text:"THE LUXORA COLLECTIVE", font:"Arial", size:18, bold:true, color:ROSE_DARK, characterSpacing:80 })] }),
  new Paragraph({ spacing:{before:0,after:0}, alignment:AlignmentType.CENTER, children:[new TextRun({ text:"theluxoracollective.co  |  Bethany Anne, Co-Founder & CEO", font:"Arial", size:17, color:MID_GRAY })] })
];

// ══════════════════════════════════════════════════════════════
// BUILD
// ══════════════════════════════════════════════════════════════
const doc = new Document({
  numbering:{ config:[{ reference:"bullets", levels:[{ level:0, format:LevelFormat.BULLET, text:"\u2022", alignment:AlignmentType.LEFT, style:{ paragraph:{ indent:{ left:560, hanging:280 } } } }] }] },
  sections:[
    { properties:{ page:{ size:{ width:12240, height:15840 }, margin:{ top:1440, right:1440, bottom:1440, left:1440 } } }, children:cover },
    { properties:pageProps, footers:{ default:makeFooter() }, children:[
      ...principles,
      ...p1, ...p2, ...p3, ...p4, ...p5, ...p6
    ]}
  ]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/home/claude/Luxora_Growth_Engine_v9.docx', buf);
  console.log('Done');
});

