{"language": "javascript", "code": "const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, ImageRun,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
  PageNumber, Footer, TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

// ── Colors ───────────────────────────────────────────
const ROSE_DARK   = "6B2737";
const ROSE_MID    = "9E3F57";
const ROSE_LIGHT  = "F7EAED";
const GOLD        = "B8935A";
const CHARCOAL    = "2C2C2C";
const WARM_GRAY   = "F4F1F0";
const MID_GRAY    = "888888";
const WHITE       = "FFFFFF";
const BORDER_CLR  = "DDD0D4";
const DEEP_DARK   = "3D1520";

// ── Borders ──────────────────────────────────────────
const thinB    = { style: BorderStyle.SINGLE, size: 1, color: BORDER_CLR };
const allB     = { top: thinB, bottom: thinB, left: thinB, right: thinB };
const noB      = { style: BorderStyle.NONE, size: 0, color: WHITE };
const noAll    = { top: noB, bottom: noB, left: noB, right: noB };
const leftRose = { top: noB, bottom: noB, right: noB, left: { style: BorderStyle.SINGLE, size: 20, color: ROSE_MID } };
const leftGold = { top: noB, bottom: noB, right: noB, left: { style: BorderStyle.SINGLE, size: 20, color: GOLD } };

function sp(b=40, a=40){ return new Paragraph({ spacing:{before:b,after:a}, children:[] }); }

function divider(color=ROSE_LIGHT){
  return new Paragraph({
    spacing:{before:60,after:60},
    border:{ bottom:{ style:BorderStyle.SINGLE, size:6, color, space:1 } },
    children:[]
  });
}

function phaseHeader(num, label, timeHint, subtitle){
  return new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: noAll,
      shading:{ fill:ROSE_DARK, type:ShadingType.CLEAR },
      margins:{ top:140, bottom:140, left:360, right:360 },
      width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({
          spacing:{before:0,after:40},
          children:[
            ...(num > 0 ? [new TextRun({ text:`PHASE ${num}  `, font:"Arial", size:17, bold:true, color:GOLD, characterSpacing:120 })] : []),
            new TextRun({ text:label.toUpperCase(), font:"Arial", size:25, bold:true, color:WHITE, characterSpacing:80 }),
            ...(timeHint ? [new TextRun({ text:`   ${timeHint}`, font:"Arial", size:17, color:"C8A8B0" })] : [])
          ]
        }),
        ...(subtitle ? [new Paragraph({
          spacing:{before:0,after:0},
          children:[new TextRun({ text:subtitle, font:"Arial", size:18, italics:true, color:"C8A8B0" })]
        })] : [])
      ]
    })] })]
  });
}

function timeBudget(text){
  return new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: noAll,
      shading:{ fill:DEEP_DARK, type:ShadingType.CLEAR },
      margins:{ top:60, bottom:60, left:240, right:240 },
      width:{ size:9360, type:WidthType.DXA },
      children:[new Paragraph({
        spacing:{before:0,after:0},
        children:[new TextRun({ text:`⏱  ${text}`, font:"Arial", size:17, bold:true, color:GOLD })]
      })]
    })] })]
  });
}

function leakHeader(label){
  return new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: noAll,
      shading:{ fill:DEEP_DARK, type:ShadingType.CLEAR },
      margins:{ top:90, bottom:90, left:300, right:300 },
      width:{ size:9360, type:WidthType.DXA },
      children:[new Paragraph({
        spacing:{before:0,after:0},
        children:[
          new TextRun({ text:"REVENUE LEAK  ", font:"Arial", size:15, bold:true, color:GOLD, characterSpacing:100 }),
          new TextRun({ text:label.toUpperCase(), font:"Arial", size:20, bold:true, color:WHITE })
        ]
      })]
    })] })]
  });
}

function say(text){
  return new Paragraph({
    spacing:{before:60,after:40},
    children:[new TextRun({ text, font:"Arial", size:22, color:CHARCOAL })]
  });
}

function pause(text){
  return new Paragraph({
    spacing:{before:40,after:40},
    indent:{left:360},
    children:[new TextRun({ text:`[PAUSE  —  ${text}]`, font:"Arial", size:18, bold:true, italics:true, color:ROSE_MID })]
  });
}

function dir(text){
  return new Paragraph({
    spacing:{before:40,after:40},
    indent:{left:360},
    children:[new TextRun({ text, font:"Arial", size:18, italics:true, color:MID_GRAY })]
  });
}

function callout(label, lines, bg=ROSE_LIGHT, lc=ROSE_DARK){
  return new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: allB,
      shading:{ fill:bg, type:ShadingType.CLEAR },
      margins:{ top:100, bottom:100, left:220, right:220 },
      width:{ size:9360, type:WidthType.DXA },
      children:[
        new Paragraph({ spacing:{before:0,after:60}, children:[new TextRun({ text:label.toUpperCase(), font:"Arial", size:17, bold:true, color:lc, characterSpacing:60 })] }),
        ...lines.map(l => new Paragraph({ spacing:{before:30,after:30}, children:[new TextRun({ text:l, font:"Arial", size:19, color:CHARCOAL })] }))
      ]
    })] })]
  });
}

function accent(lines, gold=false){
  return new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[9360],
    rows:[new TableRow({ children:[new TableCell({
      borders: gold ? leftGold : leftRose,
      shading:{ fill:WARM_GRAY, type:ShadingType.CLEAR },
      margins:{ top:100, bottom:100, left:240, right:200 },
      width:{ size:9360, type:WidthType.DXA },
      children: lines.map((l,i) => new Paragraph({
        spacing:{before:i===0?0:30,after:30},
        children:[new TextRun({ text:l, font:"Arial", size:20, italics:true, color:CHARCOAL })]
      }))
    })] })]
  });
}

function priceTable(){
  function row(a,b,bg=WHITE){
    return new TableRow({ children:[
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:140,right:140}, width:{size:5400,type:WidthType.DXA},
        children:[new Paragraph({ children:[new TextRun({ text:a, font:"Arial", size:20, color:CHARCOAL })] })] }),
      new TableCell({ borders:allB, shading:{fill:bg,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:140,right:140}, width:{size:3960,type:WidthType.DXA},
        children:[new Paragraph({ children:[new TextRun({ text:b, font:"Arial", size:20, bold:true, color:ROSE_DARK })] })] })
    ]});
  }
  return new Table({
    width:{ size:9360, type:WidthType.DXA }, columnWidths:[5400,3960],
    rows:[
      new TableRow({ children:[
        new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:140,right:140}, width:{size:5400,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:"OPTION", font:"Arial", size:17, bold:true, color:WHITE })] })] }),
        new TableCell({ borders:allB, shading:{fill:ROSE_DARK,type:ShadingType.CLEAR}, margins:{top:80,bottom:80,left:140,right:140}, width:{size:3960,type:WidthType.DXA}, children:[new Paragraph({ children:[new TextRun({ text:"INVESTMENT", font:"Arial", size:17, bold:true, color:WHITE })] })] })
      ]}),
      row("Paid in Full", "$9,000", ROSE_LIGHT),
      row("2-Pay", "$4,975 x 2", WHITE),
      row("Financing", "Klarna / Affirm", WARM_GRAY)
    ]
  });
}

// Results capture tables built as variables to avoid spread syntax issues
