        new Paragraph({ spacing:{before:0,after:0}, children:[new TextRun({ text:"This number lives in every part of Phase 4, Phase 5, and every objection handler.", font:"Arial", size:17, italics:true, color:"C8A8B0" })] })
      ]
    })] })]
  }),
];

// ══════════════════════════════════════════════════════════════
// PHASE 4 — MIRROR + REFRAME  (5 min)
// ══════════════════════════════════════════════════════════════
const p4 = [
  phaseHeader(4, "Mirror + Reframe", "(5 min)", "Her exact words from Phase 2. She just saw her number. Now she needs to feel completely understood."),
  sp(0,20),
  accent([
    "The scan showed her the logic. This phase does the emotional work that makes the decision feel obvious.",
    "Use her exact words from Phase 2 — not your interpretation, not a summary, her words.",
    "She should say 'yes, exactly' and mean it. That is the moment trust becomes commitment."
  ]),
  sp(0,20),

  say('"I want to connect something.'),
  sp(0,20),
  say('At the start of this call you told me [USE HER EXACT WORDS FROM PHASE 2 — her pain, her stuck place, her frustration].'),
  sp(0,20),
  say('And what we just saw in the scan is exactly where that feeling is coming from. It is not in your head. It is in your system.'),
  sp(0,20),
  say('Your business has been quietly leaking in four specific places, and until today no one had ever put a number on it for you.'),
  sp(0,20),
  say('Is that close to what you have been carrying?"'),
  pause("Wait. She will confirm with real emotion. Do not fill that moment."),
  sp(0,20),
  divider(),
  sp(0,10),

  say('"Here is what I want you to see.'),
  sp(0,20),
  say('The med spas that get past this point are not doing more. They are not grinding harder or throwing more money at ads.'),
  sp(0,20),
  say('They closed these gaps. And when they did, something shifted. The business stopped feeling like something they were white-knuckling every month.'),
  sp(0,20),
  say('It started running. The revenue got predictable. The owner got her time back.'),
  sp(0,20),
  say('You are not far from that. You just need the right system built under what you have already created."'),
  pause("Let that land. She is seeing the version of herself on the other side of this. The pause is everything."),
  sp(0,20),

  callout("Two questions before you pitch — do not skip these", [
    '"Is this a decision you make on your own, or is there someone else who needs to be part of this conversation?"',
    "",
    '"If you were going to fix this, when would you want that to start? What would make right now the right time?"',
    "",
    "[If someone else is involved, get their name. Do not pitch without knowing who is in the room.",
    "If there is no urgency, ask: 'What would need to be true for you to feel ready?' Then solve for that.]"
  ], WARM_GRAY, ROSE_DARK),
];

// ══════════════════════════════════════════════════════════════
// PHASE 5 — THE PITCH  (8 min)
// ══════════════════════════════════════════════════════════════
const p5 = [
  phaseHeader(5, "The Pitch", "(8 min)", "Permission first. Every pillar is an answer to something she just saw on the screen."),
  sp(0,20),

  say('"Based on everything we have been through today, I can see a real and specific path forward.'),
  sp(0,20),
  say('The revenue is already in your business. Every gap we just looked at is fixable. We just need to close them and put the right infrastructure underneath you.'),
  sp(0,20),
  say('Can I show you how we do that?"'),
  pause("Wait for yes. The yes is permission. Do not pitch without it."),
  sp(0,20),

  new Paragraph({ spacing:{before:0,after:40}, children:[new TextRun({ text:"OUR 3 PILLARS", font:"Arial", size:20, bold:true, color:ROSE_DARK, characterSpacing:100 })] }),
  pillarsImage(),
  sp(0,10),

  say('"Pillar One is the Market Blueprint.'),
  sp(0,20),
  say('Before we ever run an ad, we map your entire market. Your competitors, your pricing gaps, what is actually working in your area right now.'),
  sp(0,20),
  say('Within 72 hours you know exactly where your opportunity is before you spend a dollar. This is what starts closing your leads gap, because you stop guessing who to reach and how."'),
  dir("[Check-in: 'Does that already feel different from what you have done before?']"),
  sp(0,20),

  say('"Pillar Two is the Acquisition Engine.'),
  sp(0,20),
  say('We build and install the full system. Ads, AI follow-up, CRM, booking automation, front desk frameworks.'),
  sp(0,20),
  say('This closes your consultation and treatment conversion gaps. The follow-up goes out automatically. Your team has a real process for every conversation. You stop being the person everything runs through."'),
  dir("[Check-in: 'Can you see how this directly addresses what we found in your scan?']"),
  sp(0,20),

  say('"Pillar Three is the Revenue Multiplier.'),
  sp(0,20),
  say('This is where we go after your retention gap, the one with the biggest number.'),
  sp(0,20),
  say('Membership structures, package architecture, re-book sequences, referral systems, team sales training, partnership and collaboration strategies. Every client starts generating the kind of lifetime value your business has never actually captured before."'),
  dir("[Check-in: 'Is this the piece that has been missing?']"),
  sp(0,20),

  callout("Tie it to her number before you talk about delivery", [
    '"We found [HER TOTAL] leaking from your business. That is the floor of what we are working with.',
    "",
    "The work we do together closes those gaps. But it also builds things your business has never had before: a real membership structure, package architecture, partnership strategies, a reputation system, team training that actually sticks.",
    "",
    "The revenue we recover from closing your existing leaks alone typically covers the cost of the program by Month 3. That is just the recovery piece.",
    "",
    "Everything we build on top of that compounds. It does not stop when the 90 days ends.",
    "",
    "So the minimum outcome is this pays for itself. The real outcome is it changes what your business is capable of entirely."
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,20),

  callout("Temperature check — do this before delivery", [
    '"How are you feeling about all of this right now?"',
    "",
    "If anything less than a clear yes: 'What part of this is not landing clearly for you?'",
    "Address it fully before you say another word about the program."
  ], WARM_GRAY, ROSE_DARK),
  sp(0,20),

  say('"Here is how the 90 days actually works.'),
  sp(0,20),
  say('This is not a course. It is not a strategy deck you hand to your team and hope something sticks.'),
  sp(0,20),
  say('We build the systems, the frameworks, and the playbooks with you on bi-weekly strategy calls. You get the exact structures, the scripts, the training guides. Your team gets trained on them and we hold the standard with you throughout.'),
  sp(0,20),
  say('Does it require your participation? Yes. You are implementing this inside your own business with your own people. We are not an agency that disappears into the backend.'),
  sp(0,20),
  say('What we are is the partner who has done this enough times to know exactly what works, built it specifically for your situation, and is on the call with you every step of the way.'),
  sp(0,20),
  say('Most clients continue working with us after the 90 days. But that is entirely your choice."'),
];

// ══════════════════════════════════════════════════════════════
// PHASE 6 — PRICE + CLOSE  (7 min)
// ══════════════════════════════════════════════════════════════
const p6 = [
  phaseHeader(6, "Price + Close", "(7 min)", "State it. Stop. The silence is the close. Do not fill it."),
  sp(0,20),

  say('"To build and install The Luxora Growth Engine over the next 90 days, the investment is:"'),
  sp(0,20),
  priceTable(),
  sp(0,20),
  pause("Stop. Do not explain the price. Do not add anything. Let it sit."),
  sp(0,20),

  say('"And before you respond, I want to say one more thing.'),
  sp(0,20),
  say('If we do not generate at least two times your investment in recovered lifetime client value within 90 days, we keep working with you at no additional cost until we do.'),
  sp(0,20),
  say('As long as you follow the system, we do not stop until the number is there.'),
  sp(0,20),
  say('No agency can make that offer because they do not own the whole engine. We do."'),
  pause("Three full seconds after the guarantee. Let it land before you ask anything."),
  sp(0,20),

  say('"So based on everything we found today, and knowing what is sitting on the table right now, do you feel like this is something you are ready to fix, or are you still more in the figuring-it-out phase?"'),
  pause("Two options. No pressure. No urgency. Her answer tells you exactly where you are."),
  sp(0,20),
  divider(),
  sp(0,20),

  callout("If she says yes:", [
    '"Perfect. I am going to pull up our checkout page right now and walk you through it. It takes two minutes."',
    "",
    "go.theluxoracollective.co/the-luxora-growth-engine",
    "",
    "[Stay on the call. Walk her through every field. Do not send the link and let her go alone.]",
    "[Screen share if on video. If she is on mobile, stay quiet while she navigates. Do not rush her.]"
  ], ROSE_LIGHT, GOLD),
  sp(0,20),

  callout("If she hesitates:", [
    '"That is completely okay. What is making you feel like you are still in figuring-it-out mode?"',
    "",
    "[Full stop. Let her tell you the real thing. Do not guess. Mirror it back. Reframe it. Then close again with the same question.]"
  ], WARM_GRAY, ROSE_DARK),
  sp(0,20),

  callout("If she says 'I need to think about it':", [
    '"Of course. What would make this a clear yes for you?"',
    "",
    "She will tell you. Three common answers:",
    "  Cost: 'We found [HER TOTAL] leaking. The program is $9,000. You are not spending $9,000. You are recovering a multiple of it that is already in your pipeline.'",
    "  Partner: Get the name. Schedule a call with both of them this week.",
    "  Timing: 'What would need to change for right now to feel like the right time?' Then solve for that."
  ], WARM_GRAY, ROSE_DARK),
  sp(0,20),

  callout("If she says 'we already tried ads':", [
    '"That is exactly why we start with the system before we ever run an ad.',
    "We just showed you four places your business is leaking. Sending paid traffic into those gaps does not grow the business.",
    "It just fills a leaky bucket faster.",
    "We close the leaks first. Then we add the fuel. Every time. In that order."
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,20),

  callout("If she says 'the investment is too much':", [
    "Reference her number. Do not defend the price.",
    "",
    '"We found [HER TOTAL] leaving your business every year.',
    "The program is $9,000.",
    "You are not spending $9,000. You are recovering a multiple of $9,000 that is already inside your pipeline, from clients you already have.",
    "The real question is what it costs you to leave that on the table for another 12 months."
  ], ROSE_LIGHT, ROSE_DARK),
  sp(0,20),

  divider(GOLD),
  new Paragraph({ spacing:{before:80,after:40}, alignment:AlignmentType.CENTER,
    children:[new TextRun({ text:"THE LUXORA COLLECTIVE", font:"Arial", size:18, bold:true, color:ROSE_DARK, characterSpacing:80 })] }),
  new Paragraph({ spacing:{before:0,after:0}, alignment:AlignmentType.CENTER,
    children:[new TextRun({ text:"theluxoracollective.co  |  Bethany Anne, Co-Founder & CEO", font:"Arial", size:17, color:MID_GRAY })] })
];

// ══════════════════════════════════════════════════════════════
// BUILD
// ══════════════════════════════════════════════════════════════
const doc = new Document({
  numbering:{ config:[{ reference:"bullets", levels:[{ level:0, format:LevelFormat.BULLET, text:"\u2022", alignment:AlignmentType.LEFT, style:{ paragraph:{ indent:{ left:560, hanging:280 } } } }] }] },
  sections:[
    { properties:{ page:{ size:{ width:12240, height:15840 }, margin:{ top:1440, right:1440, bottom:1440, left:1440 } } }, children:cover },
    { properties:pageProps, footers:{ default:makeFooter() }, children:[
      ...principles,
      ...p1, ...p2, ...p3, ...p4, ...p5, ...p6
    ]}
  ]
});

Packer.toBuffer(doc).then(buf => {
  fs.writeFileSync('/home/claude/Luxora_Growth_Engine_v9_final.docx', buf);
  console.log('Done');
});
