const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell, ImageRun,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
  PageNumber, Footer, TabStopType, TabStopPosition
} = require('docx');
const fs = require('fs');

const ROSE_DARK = "6B2737";
const ROSE_MID  = "9E3F57";
const ROSE_LIGHT= "F7EAED";
const GOLD      = "B8935A";
const CHARCOAL  = "2C2C2C";
const WARM_GRAY = "F4F1F0";
const MID_GRAY  = "888888";
const WHITE     = "FFFFFF";
const BORDER_CLR= "DDD0D4";
const DEEP_DARK = "3D1520";

const thinB    = { style:BorderStyle.SINGLE, size:1, color:BORDER_CLR };
const allB     = { top:thinB, bottom:thinB, left:thinB, right:thinB };
const noB      = { style:BorderStyle.NONE, size:0, color:WHITE };
const noAll    = { top:noB, bottom:noB, left:noB, right:noB };
const leftRose = { top:noB, bottom:noB, right:noB, left:{style:BorderStyle.SINGLE,size:20,color:ROSE_MID} };
const leftGold = { top:noB, bottom:noB, right:noB, left:{style:BorderStyle.SINGLE,size:20,color:GOLD} };

function sp(b=40,a=40){ return new Paragraph({spacing:{before:b,after:a},children:[]}); }

function divider(color=ROSE_LIGHT){
  return new Paragraph({
    spacing:{before:60,after:60},
    border:{bottom:{style:BorderStyle.SINGLE,size:6,color,space:1}},
    children:[]
  });
}

function band(bg, children){
  return new Table({
    width:{size:9360,type:WidthType.DXA}, columnWidths:[9360],
    rows:[new TableRow({children:[new TableCell({
      borders:noAll, shading:{fill:bg,type:ShadingType.CLEAR},
      margins:{top:140,bottom:140,left:360,right:360}, width:{size:9360,type:WidthType.DXA},
      children
    })]})]
  });
}

function phaseHeader(num, label, timeHint, subtitle){
  return band(ROSE_DARK,[
    new Paragraph({
      spacing:{before:0,after:subtitle?40:0},
      children:[
        ...(num>0?[new TextRun({text:`PHASE ${num}  `,font:"Arial",size:17,bold:true,color:GOLD,characterSpacing:120})]:[]),
        new TextRun({text:label.toUpperCase(),font:"Arial",size:25,bold:true,color:WHITE,characterSpacing:80}),
        ...(timeHint?[new TextRun({text:`   ${timeHint}`,font:"Arial",size:17,color:"C8A8B0"})]:[])
      ]
    }),
    ...(subtitle?[new Paragraph({spacing:{before:0,after:0},children:[new TextRun({text:subtitle,font:"Arial",size:18,italics:true,color:"C8A8B0"})]})]:[])
  ]);
}

function timeBudget(text){
  return band(DEEP_DARK,[
    new Paragraph({spacing:{before:0,after:0},children:[new TextRun({text:`⏱  ${text}`,font:"Arial",size:17,bold:true,color:GOLD})]})
  ]);
}

function leakBand(label){
  return band(DEEP_DARK,[
    new Paragraph({spacing:{before:0,after:0},children:[
      new TextRun({text:"REVENUE LEAK  ",font:"Arial",size:15,bold:true,color:GOLD,characterSpacing:100}),
      new TextRun({text:label.toUpperCase(),font:"Arial",size:20,bold:true,color:WHITE})
    ]})
  ]);
}

function say(text){
  return new Paragraph({spacing:{before:60,after:40},children:[new TextRun({text,font:"Arial",size:22,color:CHARCOAL})]});
}

function pause(text){
  return new Paragraph({
    spacing:{before:40,after:40},indent:{left:360},
    children:[new TextRun({text:`[PAUSE  —  ${text}]`,font:"Arial",size:18,bold:true,italics:true,color:ROSE_MID})]
  });
}

function dir(text){
  return new Paragraph({
    spacing:{before:40,after:40},indent:{left:360},
    children:[new TextRun({text,font:"Arial",size:18,italics:true,color:MID_GRAY})]
  });
}

function writeLine(){
  return new Paragraph({
    spacing:{before:20,after:40},
    children:[new TextRun({text:"Her words:  _____________________________________________________________________________",font:"Arial",size:18,color:BORDER_CLR})]
  });
}

function callout(label, lines, bg=ROSE_LIGHT, lc=ROSE_DARK){
  return new Table({
    width:{size:9360,type:WidthType.DXA}, columnWidths:[9360],
    rows:[new TableRow({children:[new TableCell({
      borders:allB, shading:{fill:bg,type:ShadingType.CLEAR},
      margins:{top:100,bottom:100,left:220,right:220}, width:{size:9360,type:WidthType.DXA},
      children:[
        new Paragraph({spacing:{before:0,after:60},children:[new TextRun({text:label.toUpperCase(),font:"Arial",size:17,bold:true,color:lc,characterSpacing:60})]}),
        ...lines.map(l=>new Paragraph({spacing:{before:30,after:30},children:[new TextRun({text:l,font:"Arial",size:19,color:CHARCOAL})]}))
      ]
    })]})]
  });
}

function accent(lines, gold=false){
  return new Table({
    width:{size:9360,type:WidthType.DXA}, columnWidths:[9360],
    rows:[new TableRow({children:[new TableCell({
      borders:gold?leftGold:leftRose, shading:{fill:WARM_GRAY,type:ShadingType.CLEAR},
      margins:{top:100,bottom:100,left:240,right:200}, width:{size:9360,type:WidthType.DXA},
      children:lines.map((l,i)=>new Paragraph({spacing:{before:i===0?0:30,after:30},children:[new TextRun({text:l,font:"Arial",size:20,italics:true,color:CHARCOAL})]}))
    })]})]
  });
}

function priceTable(){
  function row(a,b,bg=WHITE){
    return new TableRow({children:[
      new TableCell({borders:allB,shading:{fill:bg,type:ShadingType.CLEAR},margins:{top:80,bottom:80,left:140,right:140},width:{size:5400,type:WidthType.DXA},children:[new Paragraph({children:[new TextRun({text:a,font:"Arial",size:20,color:CHARCOAL})]})]  }),
      new TableCell({borders:allB,shading:{fill:bg,type:ShadingType.CLEAR},margins:{top:80,bottom:80,left:140,right:140},width:{size:3960,type:WidthType.DXA},children:[new Paragraph({children:[new TextRun({text:b,font:"Arial",size:20,bold:true,color:ROSE_DARK})]})]  })
    ]});
  }
  return new Table({
    width:{size:9360,type:WidthType.DXA}, columnWidths:[5400,3960],
    rows:[
      new TableRow({children:[
        new TableCell({borders:allB,shading:{fill:ROSE_DARK,type:ShadingType.CLEAR},margins:{top:80,bottom:80,left:140,right:140},width:{size:5400,type:WidthType.DXA},children:[new Paragraph({children:[new TextRun({text:"OPTION",font:"Arial",size:17,bold:true,color:WHITE})]})] }),
        new TableCell({borders:allB,shading:{fill:ROSE_DARK,type:ShadingType.CLEAR},margins:{top:80,bottom:80,left:140,right:140},width:{size:3960,type:WidthType.DXA},children:[new Paragraph({children:[new TextRun({text:"INVESTMENT",font:"Arial",size:17,bold:true,color:WHITE})]})] })
      ]}),
      row("Paid in Full","$9,000",ROSE_LIGHT),
      row("2-Pay","$4,975 x 2",WHITE),
      row("Financing","Klarna / Affirm",WARM_GRAY)
    ]
  });
}

// Results table — built explicitly to avoid spread syntax issues
function makeCell(text, bg, w, bold=false, italic=false){
  return new TableCell({borders:allB,shading:{fill:bg,type:ShadingType.CLEAR},margins:{top:70,bottom:70,left:120,right:120},width:{size:w,type:WidthType.DXA},
    children:[new Paragraph({children:[new TextRun({text,font:"Arial",size:18,bold,italics:italic,color:bold?ROSE_DARK:MID_GRAY})]})]});
}
function makeHCell(text){
  return new TableCell({borders:allB,shading:{fill:ROSE_DARK,type:ShadingType.CLEAR},margins:{top:70,bottom:70,left:120,right:120},width:{size:0,type:WidthType.DXA},
    children:[new Paragraph({children:[new TextRun({text,font:"Arial",size:16,bold:true,color:WHITE})]})]});
}
const resultsTable = new Table({
  width:{size:9360,type:WidthType.DXA}, columnWidths:[3200,2080,2080,2000],
  rows:[
    new TableRow({children:[makeHCell("METRIC"),makeHCell("HER NUMBER"),makeHCell("BENCHMARK"),makeHCell("GAP")]}),
    new TableRow({children:[makeCell("Leads",ROSE_LIGHT,3200,true),makeCell("___",ROSE_LIGHT,2080),makeCell("140/mo",ROSE_LIGHT,2080,false,true),makeCell("___",ROSE_LIGHT,2000)]}),
    new TableRow({children:[makeCell("Consultations",WHITE,3200,true),makeCell("___",WHITE,2080),makeCell("60/mo",WHITE,2080,false,true),makeCell("___",WHITE,2000)]}),
    new TableRow({children:[makeCell("Treatments",ROSE_LIGHT,3200,true),makeCell("___",ROSE_LIGHT,2080),makeCell("31/mo",ROSE_LIGHT,2080,false,true),makeCell("___",ROSE_LIGHT,2000)]}),
    new TableRow({children:[makeCell("Repeat Clients",WHITE,3200,true),makeCell("___",WHITE,2080),makeCell("16/mo",WHITE,2080,false,true),makeCell("___",WHITE,2000)]})
  ]
});

const totalsTable = new Table({
  width:{size:9360,type:WidthType.DXA}, columnWidths:[4680,4680],
  rows:[new TableRow({children:[
    new TableCell({borders:allB,shading:{fill:DEEP_DARK,type:ShadingType.CLEAR},margins:{top:100,bottom:100,left:160,right:160},width:{size:4680,type:WidthType.DXA},
      children:[new Paragraph({spacing:{before:0,after:40},children:[new TextRun({text:"MONTHLY REVENUE GAP",font:"Arial",size:16,bold:true,color:GOLD,characterSpacing:60})]}),
                new Paragraph({spacing:{before:0,after:0},children:[new TextRun({text:"$___________________ /mo",font:"Arial",size:22,bold:true,color:WHITE})]})]}),
    new TableCell({borders:allB,shading:{fill:ROSE_DARK,type:ShadingType.CLEAR},margins:{top:100,bottom:100,left:160,right:160},width:{size:4680,type:WidthType.DXA},
      children:[new Paragraph({spacing:{before:0,after:40},children:[new TextRun({text:"ANNUAL LOST REVENUE",font:"Arial",size:16,bold:true,color:GOLD,characterSpacing:60})]}),
                new Paragraph({spacing:{before:0,after:0},children:[new TextRun({text:"$___________________ /yr",font:"Arial",size:22,bold:true,color:WHITE})]})
    ]})
  ]})]
});

const imgData = fs.readFileSync('/home/claude/pillars.png');
function pillarsImage(){
  return new Paragraph({
    spacing:{before:80,after:80},alignment:AlignmentType.CENTER,
    children:[new ImageRun({type:"png",data:imgData,transformation:{width:624,height:416},
      altText:{title:"The Luxora 3 Pillars",description:"Market Blueprint, Acquisition Engine, Revenue Multiplier",name:"pillars"}})]
  });
}

function makeFooter(){
  return new Footer({children:[new Paragraph({
    tabStops:[{type:TabStopType.RIGHT,position:TabStopPosition.MAX}],
    children:[
      new TextRun({text:"THE LUXORA COLLECTIVE  |  Growth Engine Discovery Call",font:"Arial",size:16,color:MID_GRAY}),
      new TextRun({text:"\tPage ",font:"Arial",size:16,color:MID_GRAY}),
      new TextRun({children:[PageNumber.CURRENT],font:"Arial",size:16,color:MID_GRAY})
    ]
  })]});
}

const pageProps = {page:{size:{width:12240,height:15840},margin:{top:1080,right:1440,bottom:1080,left:1440}}};

// ── COVER ─────────────────────────────────────────────
const cover = [
  band(ROSE_DARK,[
    new Paragraph({spacing:{before:0,after:40},children:[new TextRun({text:"THE LUXORA COLLECTIVE",font:"Arial",size:18,bold:true,color:"C8A8B0",characterSpacing:120})]}),
    new Paragraph({spacing:{before:0,after:120},border:{bottom:{style:BorderStyle.SINGLE,size:4,color:GOLD,space:1}},children:[]}),
    new Paragraph({spacing:{before:140,after:60},children:[new TextRun({text:"Growth Engine",font:"Arial",size:52,bold:true,color:WHITE})]}),
    new Paragraph({spacing:{before:0,after:60},children:[new TextRun({text:"Discovery Call Script",font:"Arial",size:30,bold:true,color:WHITE})]}),
    new Paragraph({spacing:{before:0,after:200},children:[new TextRun({text:"With Live Revenue Leak Scan",font:"Arial",size:22,color:GOLD,italics:true})]}),
